	@Override
	public String AddMailTemp(String st, String subject, String mailbody, String company, String emailTrigger,
			String ticketType, String mailfooter) {
		//// //System.out.println("Inside MasterDaoImpl mailtemp method");
		String status = null;
		String output = "";

		try {
			//// //System.out.println("Before Projection List ");
			Session s = getSession();
			////// //System.out.println("s =" + s);

			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(ADD_MAIL_TEMPLATE.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				////// //System.out.println(" SRNO IS: " + srno1);

				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					////// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside adduser status====" + st);
			//// //System.out.println("ticket Type ======" + ticketType);
			Query query = sessionFactory.getCurrentSession()
					.createQuery("from ADD_MAIL_TEMPLATE where STATUS= :u and TICKET_TYPE=:TICKET_TYPE"
							+ " and COMPANY='" + company + "' ");
			query.setParameter("u", st);
			query.setParameter("TICKET_TYPE", ticketType);
			;

			ADD_MAIL_TEMPLATE data = (ADD_MAIL_TEMPLATE) query.uniqueResult();

			if (data != null) {
				output = "duplicate";
				//// //System.out.println("inaide duplicate");
			} else {
				//// //System.out.println("in else block to insert new record");
				//
				ADD_MAIL_TEMPLATE user1 = new ADD_MAIL_TEMPLATE();

				user1.setSR_NO(srno);
				user1.setSTATUS(st);
				user1.setSUBJECT(subject);
				user1.setMAILBODY(mailbody);
				user1.setCOMPANY(company);
				user1.setEMAIL_TRIGGER(emailTrigger);
				user1.setTICKET_TYPE(ticketType);
				// if(mailfooter)
				user1.setMAIL_FOOTER(mailfooter);

				sessionFactory.getCurrentSession().persist(user1);
				output = "success";
			}

		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return output;

	}

