	@Override
	public String adduserEmail(String company, String mail, String subject, String folder, String port, String uname,
			String pass, String starttls) {
		//// //System.out.println("Inside MasterDaoImpl adduser method");
		String status = null;
		try {
			//// //System.out.println("Before Projection List ");
			Session s = getSession();
			//// //System.out.println("s =" + s);

			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(EMAIL_LISTENER.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				//// //System.out.println(" SRNO IS: " + srno1);

				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					//// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside adduser");
			Query query = sessionFactory.getCurrentSession()
					.createQuery("from EMAIL_LISTENER where COMPANY_NAME='" + company + "'");
			List listOfCompany = query.list();
			if (!listOfCompany.isEmpty()) {
				status = "duplicate";
			} else {
				EMAIL_LISTENER user1 = new EMAIL_LISTENER();

				user1.setSR_NO(srno);
				user1.setCOMPANY_NAME(company);
				user1.setMAIL_SERVER(mail);
				user1.setSUBJECT_RESTRICTION(subject);
				user1.setEMAIL_FOLDER(folder);
				user1.setPORT(port);
				user1.setUSERNAME(uname);
				user1.setPASSWORD(pass);

				sessionFactory.getCurrentSession().persist(user1);
				status = "success";

			}

		} catch (Exception e) {
			e.printStackTrace();

		}

		return status;
//		return null;
	}

