	@Override
	public JSONArray getCategoryDetails(String catname) {
		//// //System.out.println("Inside MasterDaoImpl getCategoryDetails method");

		JSONArray array = null;
		JSONArray array1 = null;
		String loginUserCompany = "";
		try {
			ServletRequestAttributes requestAttributes = (ServletRequestAttributes) RequestContextHolder
					.getRequestAttributes();
			HttpSession session = requestAttributes.getRequest().getSession();
			loginUserCompany = session.getAttribute("companyname").toString();
			//// //System.out.println("loginUserCompany****" + loginUserCompany);
		} catch (Exception e) {
			e.printStackTrace();
			//// //System.out.println("Exceptioon e***" + e);
		}
		try {
			Criteria criteria = sessionFactory.getCurrentSession().createCriteria(categorymaster.class);
			criteria.setProjection(Projections.distinct(Projections.property("CAT_NAME")))
					.add(Restrictions.eq("COMPANY", loginUserCompany));
			List<String> dataList = criteria.list();
			//// //System.out.println("LIST FETCHED: " + dataList);
			array1 = new JSONArray();
			TreeSet<String> treeset = new TreeSet<String>();
			for (String catname1 : dataList) {

				treeset.add(catname1);
			}
			for (String str1 : treeset) {
				array = new JSONArray();
				array.put(str1);
				array1.put(array);
			}

		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return array1;
	}

