			//// //System.out.println("company AD=" + cname);
			String hql = "UPDATE AD_USER_MANAGE set USERTYPE= :UTYPE,NAME=:NAME1,EMAIL=:EMAIL1,PHONE_NO=:PHONE_NO1,COMPANY=:cname WHERE SR_NO= :id";

