	@Override
	public String ADDAdminMaster(String cno, String user, String pass, String cpass) {

		//// //System.out.println("Inside MasterDaoImpl ADDAdminMaster method");
		String status = null;

		try {
			//// //System.out.println("Before Projection List ");
			Session s = getSession();
			//// //System.out.println("s =" + s);
			//// //System.out.println("cno: " + cno + "user: " + user + "pass: " + pass +
			//// "cpass: " + cpass);
			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(Login.class)
						.setProjection(Projections.max("USERID"));
				Integer srno1 = (Integer) crit.uniqueResult();

				//// //System.out.println(" SRNO IS: " + srno1);

				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					//// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside addIT_Head");
			Query query = sessionFactory.getCurrentSession().createQuery("from Login where USERNAME=:u");
			query.setParameter("u", user);
			Login data = (Login) query.uniqueResult();
			if (data != null) {
				status = "duplicate";
			} else {
				Login user1 = new Login();

				user1.setUSERID(srno);

				user1.setPHONE(cno);
				user1.setUSERNAME(user);
				user1.setPASSWORD(pass);
				user1.setUSERTYPE("Admin");

				sessionFactory.getCurrentSession().save(user1);
				status = "success";
//				sessionFactory.getCurrentSession().save(new otp_check(srno, cno, "1234", "Admin"));
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;
	}

