	@Override
	public JSONArray getSubCategoryEnggName(String category, String Company, String Branch, String Department) {

		//// //System.out.println("Inside MasterDaoImpl getSubCategoryEnggName
		//// getSubCategoryEnggName method");
		String db_sname = null;
		JSONArray array = null;
		JSONArray array1 = new JSONArray();

		try {

			List<loginmaster> catList = sessionFactory.getCurrentSession()
					.createQuery("from loginmaster where ROLE_TYPE='Engineer' and CATEGORY IS NOT NULL").list();
			for (loginmaster catDrive : catList) {

				////// CHECK SCOPE /////
				//// //System.out.println("----------- START----------");
				String ScopeDB = catDrive.getLOGIN_SCOPE();
				//// //System.out.println("ENGG NAME: " + catDrive.getUSERNAME());
				//// //System.out.println("ENGG COMPANY: " + catDrive.getCOMPANY());
				//// //System.out.println("SCOPE DB: " + ScopeDB);
				/////// SPLIT STRING FOR 'OR' KEYWORD ///////////
				String[] SplitArray = ScopeDB.split("OR");
				/////// ITERATE STRING FOR 'OR' KEYWORD ///////////
				for (String splitString : SplitArray) {
					//// //System.out.println("SPLIT STRING FOUND: " + splitString);
					String fetchCompany = StringUtils.substringBetween(splitString, "T_COMPANY IN ('", "')");
					String fetchBranch = StringUtils.substringBetween(splitString, "T_BRANCH IN ('", "')");
					String fetchDepartment = StringUtils.substringBetween(splitString, "T_DEPARTMENT IN ('", "')");

					///////////////// COMPARE COMPANY //////////////////
					//// //System.out.println("FETCH COMPANY: " + fetchCompany);
					Boolean CompanyFlag = false;
					if (fetchCompany == null) {
						CompanyFlag = false;
					} else if (fetchCompany.equals(Company)) {
						CompanyFlag = true;
					}
					//// //System.out.println("FETCH COMPANY FINAL: " + fetchCompany);
					//// //System.out.println("FETCH COMPANY FROM INPUT: " + Company);
					//// //System.out.println("FETCH COMPANY FLAG: " + CompanyFlag);

					////////////////////// COMPARE BRANCH ////////////////
					Boolean BranchFlag = false;
					String finalBranch = "";
					if (fetchBranch == null) {
						finalBranch = "";
						BranchFlag = false;
						//// //System.out.println("FETCH BRANCH NULL: " + finalBranch);
					} else if (fetchBranch.contains(",")) {
						String[] fetchBranchArray = fetchBranch.split(",");
						for (String branchArray : fetchBranchArray) {
							finalBranch = branchArray.replaceAll("'", "");
							;
							//// //System.out.println("FETCH BRANCH LOOP: " + finalBranch);
							if (finalBranch.equals(Branch)) {
								BranchFlag = true;
								break;
							}

						}
					} else {
						finalBranch = fetchBranch;
						if (finalBranch.equals(Branch)) {
							BranchFlag = true;
						}
					}

					Boolean DepartmentFlag = false;
					String finalDepartment = "";
					if (fetchDepartment == null) {
						finalDepartment = "";
						DepartmentFlag = false;
						//// //System.out.println("FETCH DEPARTMENT NULL: " + finalDepartment);
					} else if (fetchDepartment.contains(",")) {
						String[] fetchDepartmentArray = fetchDepartment.split(",");
						for (String DepartmentArray : fetchDepartmentArray) {
							finalDepartment = DepartmentArray.replaceAll("'", "");

							//// //System.out.println("FETCH DEPARTMENT LOOP: " + finalDepartment);
							if (finalDepartment.equals(Department)) {
								DepartmentFlag = true;
								break;
							}

						}
					} else {
						finalDepartment = fetchDepartment;
						if (finalDepartment.equals(Department)) {
							DepartmentFlag = true;
						}
					}

					String catTemp = catDrive.getCATEGORY().toString();
//					 System.out.println("CATEGORY FOUND: " + catTemp);
					String[] catArray = catTemp.split(",");
					for (int i = 0; i < catArray.length; i++) {
						if (category.contentEquals(catArray[i]) && CompanyFlag && BranchFlag && DepartmentFlag) {
//							 System.out.println("CATEGORY MATCH: " + catArray[i]);
							// System.out.println("ENGINEER FOUND: " + catDrive.getUSERNAME());
							//// //System.out.println("ENGINEER COMPANY: " + catDrive.getCOMPANY());

//							 array = new JSONArray();	
//							array.put(catDrive.getUSERNAME() + "~" + catDrive.getFULL_NAME() + "~"+ catDrive.getCOMPANY());

							String enggVal = catDrive.getUSERNAME() + "~" + catDrive.getFULL_NAME() + "~"
									+ catDrive.getCOMPANY();
							array1.put(enggVal);
							System.out.println("ARRAY1PPPPPPPPP: " + array1);
						}
					}
					//// //System.out.println("------------END----------------");
				}

			}

//			List<loginmaster> dataList = sessionFactory.getCurrentSession()
//					.createQuery("from loginmaster where CATEGORY IN('" + category + "') and ROLE_TYPE='Engineer'").list();
//			array1 = new JSONArray();
//			for (loginmaster sourceDrive : dataList) {
//				//////System.out.println("array = " + sourceDrive.getUSERNAME());
//				array = new JSONArray();
//				array.put(sourceDrive.getUSERNAME());
//				array1.put(array);
//			}

		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return array1;
	}

