	@Override
	public String SubmitEscalationDetails(String engLevel, int days, int hours, int minutes, int seconds,
			String companyname, String priority, String severity, String designation, String username) {
		//// //System.out.println("Inside MASTERDaoImpl SubmitEscalationDetails
		//// method");
		String status = null;
		int daysToSeconds = 0;
		int hoursToSeconds = 0;
		int minutesToSeconds = 0;
		int totalSeconds = 0;

		try {
			//// //System.out.println("priority:" + engLevel + " days:" + days + " hours:" +
			//// hours + " minutes:" + minutes
			// + "seconds: " + seconds);

			daysToSeconds = days * 24 * 60 * 60;
			//// //System.out.println("DAYS TO SECONDS: " + daysToSeconds);

			hoursToSeconds = hours * 60 * 60;
			//// //System.out.println("HOURS TO SECONDS: " + hoursToSeconds);

			minutesToSeconds = minutes * 60;
			//// //System.out.println("MINUTES TO SECONDS: " + minutesToSeconds);

			totalSeconds = daysToSeconds + hoursToSeconds + minutesToSeconds + seconds;
			//// //System.out.println("TOTAL SECONDS: " + String.valueOf(totalSeconds));

			//// //System.out.println("inside SubmitEscalationDetails");

			// Adding Sr_no

			Criteria crit = sessionFactory.getCurrentSession().createCriteria(esc_master.class)
					.setProjection(Projections.max("SR_NO"));
			Integer srno1 = (Integer) crit.uniqueResult();
			int srno = 0;
			//// //System.out.println(" SRNO IS: " + srno1);

			if (srno1 != null) {
				srno = srno1.intValue();
				srno = srno + 1;
				//// //System.out.println("IN IF SRNO IS: " + srno);
			} else {
				srno = 1;
				//// //System.out.println("IN ELSE SRNO IS: " + srno);
			}

			Query query = sessionFactory.getCurrentSession().createQuery(
					"from esc_master where COMPANY = :COMPANY and PRIORITY_NAME = :PRIORITY_NAME and SEVERITY_NAME = :SEVERITY_NAME and ESCALATION_LEVEL= :ESCALATION_LEVEL");
			query.setParameter("COMPANY", companyname);
			query.setParameter("PRIORITY_NAME", priority);
			query.setParameter("SEVERITY_NAME", severity);
			query.setParameter("ESCALATION_LEVEL", engLevel);

			esc_master data = (esc_master) query.uniqueResult();
			if (data != null) {

				Query query1 = sessionFactory.getCurrentSession().createQuery(
						"update esc_master set ESCALATION_TIME = :ESCALATION_TIME where COMPANY = :COMPANY and ESCALATION_LEVEL= :ESCALATION_LEVEL and PRIORITY_NAME = :PRIORITY_NAME and SEVERITY_NAME = :SEVERITY_NAME");

				query1.setParameter("ESCALATION_TIME", String.valueOf(totalSeconds));
				query1.setParameter("COMPANY", companyname);
				query1.setParameter("ESCALATION_LEVEL", engLevel);
				query1.setParameter("PRIORITY_NAME", priority);
				query1.setParameter("SEVERITY_NAME", severity);

				int i = query1.executeUpdate();

				if (i == 0) {
					status = "error";
				} else {

					status = "duplicate";
				}
			} else {
				esc_master esc_master1 = new esc_master();
				esc_master1.setSR_NO(srno);
				esc_master1.setESCALATION_LEVEL(engLevel);
				esc_master1.setESCALATION_TIME(String.valueOf(totalSeconds));
				esc_master1.setCOMPANY(companyname);
				esc_master1.setPRIORITY_NAME(priority);
				esc_master1.setSEVERITY_NAME(severity);
				esc_master1.setMANAGEMENT_DESIGNATION(designation);
				esc_master1.setMANAGEMENT_USERNAME(username);
				getSession().persist(esc_master1);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;

	}

	@Override
	public JSONArray EscalationMasterListing(String escMasterList) {
		//// //System.out.println("Inside MASTERDaoImpl EscalationMasterListing
		//// method");
		JSONArray array = null;

		JSONArray array1 = null;
		int srno = 0;

		try {
			long totalSeconds = 0;

			Query query = getSession().createQuery("from esc_master");

			List<esc_master> dataList = query.list();
			array1 = new JSONArray();
			for (esc_master sourceDrive : dataList) {
				srno = srno + 1;
//				//////System.out.println("array = " + sourceDrive.getCompany());
				array = new JSONArray();

				array.put(srno);

				array.put("<button class='btn btn-danger' id='Delete'  name='Doem' onclick='DeleteEscalation(\""
						+ sourceDrive.getCOMPANY() + "\",\"" + sourceDrive.getESCALATION_LEVEL()
						+ "\" )'><i class='fa fa-trash'></i></button>");

				array.put(sourceDrive.getCOMPANY());
				array.put(sourceDrive.getPRIORITY_NAME());
				array.put(sourceDrive.getSEVERITY_NAME());
				array.put(sourceDrive.getESCALATION_LEVEL());
				totalSeconds = Long.parseLong(sourceDrive.getESCALATION_TIME());
				int day = (int) TimeUnit.SECONDS.toDays(totalSeconds);
				long hours = TimeUnit.SECONDS.toHours(totalSeconds) - (day * 24);
				long minute = TimeUnit.SECONDS.toMinutes(totalSeconds) - (TimeUnit.SECONDS.toHours(totalSeconds) * 60);
				long second = TimeUnit.SECONDS.toSeconds(totalSeconds)
						- (TimeUnit.SECONDS.toMinutes(totalSeconds) * 60);

				array.put(day);
				array.put(hours);
				array.put(minute);
				array.put(second);
				array.put(sourceDrive.getMANAGEMENT_DESIGNATION());
				array.put(sourceDrive.getMANAGEMENT_USERNAME());

				array1.put(array);

			}

		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}
		//// //System.out.println("array1==" + array1);
//	return db_password + "~" + db_username + "~" + db_usertype;
		return array1;
	}

