	@Override
	public String addProblemCategory(String category, String subcategory1, String subcategory2) {
		//// //System.out.println("Inside MasterDaoImpl addProblemCategory method");
		String status = null;

		try {
			//// //System.out.println("Before Projection List ");
			Session s = getSession();
			//// //System.out.println("s =" + s);
			//// //System.out.println("category: " + category);
			//// //System.out.println("subcategory1: " + subcategory1);
			//// //System.out.println("subcategory2: " + subcategory2);

			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(problemcategorymaster.class)
						.setProjection(Projections.max("PCAT_ID"));
				Integer srno1 = (Integer) crit.uniqueResult();

				//// //System.out.println(" SRNO IS: " + srno1);

				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					//// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside addProblemCategory");
			Query query = sessionFactory.getCurrentSession().createQuery(
					"from problemcategorymaster where PCAT_NAME=:PCAT_NAME and PSUB_CAT1=:PSUB_CAT1 and PSUB_CAT2=:PSUB_CAT2");
			query.setParameter("PCAT_NAME", category);
			query.setParameter("PSUB_CAT1", subcategory1);
			query.setParameter("PSUB_CAT2", subcategory2);

			problemcategorymaster data = (problemcategorymaster) query.uniqueResult();
			if (data != null) {
				status = "duplicate";
			} else {
				problemcategorymaster problemcategorymaster1 = new problemcategorymaster();

				problemcategorymaster1.setPCAT_ID(srno);
				problemcategorymaster1.setPCAT_NAME(category);
				problemcategorymaster1.setPSUB_CAT1(subcategory1);
				problemcategorymaster1.setPSUB_CAT2(subcategory2);

				sessionFactory.getCurrentSession().save(problemcategorymaster1);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;

	}

