	@Override
	public String addMFAType(String priority) {

		//// //System.out.println("Inside MasterDaoImpl addMFAType method");
		//// //System.out.println("Authentication_Type:-" + priority);
		String status = null;
		int id = 0;

		try {

			Integer srno1 = (Integer) sessionFactory.getCurrentSession()
					.createCriteria(TwoFactorAuthenticationType.class).setProjection(Projections.max("SRNO"))
					.uniqueResult();
			//// //System.out.println(" SRNO IS: " + srno1);

			if (srno1 != null) {
				id = srno1.intValue();
				id = id + 1;
				//// //System.out.println("IN IF SRNO IS: " + id);
			} else {
				id = 1;
				//// //System.out.println("IN ELSE SRNO IS: " + id);
			}
		} catch (Exception e) {
			// TODO Auto-generated catch block
			e.printStackTrace();
			//// //System.out.println(e);
		}

		try {
			if (id > 1) {
				Query query1 = sessionFactory.getCurrentSession().createQuery(
						"update TwoFactorAuthenticationType set Authentication_Type =:Authentication_Type ");

				query1.setParameter("Authentication_Type", priority);

				int updateVal = query1.executeUpdate();
				if (updateVal != 0 && updateVal > 0) {
					status = "success";
				} else {
					status = "error";
				}
				//// //System.out.println("updateVal of Authentication_Type:-" + updateVal);
			} else {

				TwoFactorAuthenticationType tfa = new TwoFactorAuthenticationType();

				tfa.setSRNO(id);
				tfa.setAuthentication_Type(priority);
				sessionFactory.getCurrentSession().persist(tfa);
				status = "insert";
			}
		} catch (Exception e) {
			status = "error";
			//// //System.out.println("Exception in update Authentication_Type:-" + e);
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;
	}

	@Override
	public String updateTheme(String type, String value) {
		//// //System.out.println("Inside MasterDaoImpl updateTheme method");
		String status = null;
		Query query = null;
		String LoginUser = null;
		try {
			ServletRequestAttributes requestAttributes = (ServletRequestAttributes) RequestContextHolder
					.getRequestAttributes();
			HttpSession session = requestAttributes.getRequest().getSession();
			LoginUser = session.getAttribute("username").toString();
			//// //System.out.println("username****" + LoginUser);
		} catch (Exception e) {
			e.printStackTrace();
			//// //System.out.println("Exceptioon e***" + e);
		}
		try {
			if (type.equals("NavBar")) {
				query = sessionFactory.getCurrentSession()
						.createQuery("update loginmaster set HEADER_COLOR = :HEADER_COLOR where USERNAME = :USERNAME");
				query.setParameter("HEADER_COLOR", value);
				query.setParameter("USERNAME", LoginUser);

			} else if (type.equals("SideBar")) {
				query = sessionFactory.getCurrentSession().createQuery(
						"update loginmaster set SIDEBAR_COLOR = :SIDEBAR_COLOR where USERNAME = :USERNAME");
				query.setParameter("SIDEBAR_COLOR", value);
				query.setParameter("USERNAME", LoginUser);

			} else if (type.equals("SmallBody")) {
				query = sessionFactory.getCurrentSession()
						.createQuery("update loginmaster set SMALL_FONT = :SMALL_FONT where USERNAME = :USERNAME");
				query.setParameter("SMALL_FONT", value);
				query.setParameter("USERNAME", LoginUser);

			}

			int i = query.executeUpdate();

			if (i == 0) {
				status = "error";
			} else {

				status = "success";
			}

		} catch (Exception e) {
			e.printStackTrace();

		}

		return status;
	}

	@Override
	public JSONArray getThemeData(String nodata) {

		String LoginUser = null;
		JSONArray array1 = null;
		try {
			ServletRequestAttributes requestAttributes = (ServletRequestAttributes) RequestContextHolder
					.getRequestAttributes();
			HttpSession session = requestAttributes.getRequest().getSession();
			LoginUser = session.getAttribute("username").toString();
			//// //System.out.println("username****" + LoginUser);
		} catch (Exception e) {
			e.printStackTrace();
			//// //System.out.println("Exceptioon e***" + e);
		}
		try {
			List<loginmaster> userlist = sessionFactory.getCurrentSession()
					.createQuery("from loginmaster where USERNAME ='" + LoginUser + "'").list();
			array1 = new JSONArray();
			for (loginmaster userDrive : userlist) {
				JSONObject arrayobj = new JSONObject();

				if (userDrive.getHEADER_COLOR() == null || userDrive.getHEADER_COLOR().equals("")) {
					arrayobj.put("HEADER_COLOR", "");
				} else {
					arrayobj.put("HEADER_COLOR", userDrive.getHEADER_COLOR());
				}

				if (userDrive.getSIDEBAR_COLOR() == null || userDrive.getSIDEBAR_COLOR().equals("")) {
					arrayobj.put("SIDEBAR_COLOR", "");
				} else {
					arrayobj.put("SIDEBAR_COLOR", userDrive.getSIDEBAR_COLOR());
				}

				if (userDrive.getSMALL_FONT() == null || userDrive.getSMALL_FONT().equals("")) {
					arrayobj.put("SMALL_FONT", "");
				} else {
					arrayobj.put("SMALL_FONT", userDrive.getSMALL_FONT());
				}

				array1.put(arrayobj);
				//// //System.out.println("ARRAY THEME: " + array1);
			}
		} catch (Exception e) {
			e.printStackTrace();
		}

		return array1;
	}

