	@Override
	public String addComposite(String company, String branch, String location, String department,
			String subDepartment) {
		//// //System.out.println("Inside MasterDaoImpl addComposite method");
		String status = null;

		try {
			//// //System.out.println("Before Projection List ");
			Session s = getSession();
			//// //System.out.println("s =" + s);
			//// //System.out.println("company: " + company);
			//// //System.out.println("branch: " + branch);
			//// //System.out.println("location: " + location);
			//// //System.out.println("department: " + department);
			//// //System.out.println("subDepartment: " + subDepartment);

			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(compositemaster.class)
						.setProjection(Projections.max("PCOM_ID"));
				Integer srno1 = (Integer) crit.uniqueResult();

				//// //System.out.println(" SRNO IS: " + srno1);

				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					//// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside addComposite");
			Query query = sessionFactory.getCurrentSession().createQuery(
					"from compositemaster where COMPANY=:COMPANY and BRANCH=:BRANCH and LOCATION=:LOCATION and DEPARTMENT=:DEPARTMENT and SUB_DEPARTMENT=:SUB_DEPARTMENT");
			query.setParameter("COMPANY", company);
			query.setParameter("BRANCH", branch);
			query.setParameter("LOCATION", location);
			query.setParameter("DEPARTMENT", department);
			query.setParameter("SUB_DEPARTMENT", subDepartment);

			compositemaster data = (compositemaster) query.uniqueResult();
			if (data != null) {
				status = "duplicate";
			} else {
				compositemaster compositemaster1 = new compositemaster();

				compositemaster1.setPCOM_ID(srno);
				compositemaster1.setCOMPANY(company);
				compositemaster1.setBRANCH(branch);
				compositemaster1.setLOCATION(location);
				compositemaster1.setDEPARTMENT(department);
				compositemaster1.setSUB_DEPARTMENT(subDepartment);

				sessionFactory.getCurrentSession().save(compositemaster1);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;

	}

