	public String updateUserLoginMaster(String mail, String cno, String user, String pass, String fname, String lname,
			String cpass, String cname, String sname, String dname, String category, int cr_no, String englevel,
			String rtypeupdate, String row, String subdnameupdate, String vipLogin, String updatecategory,
			String updategroup, String designation, String visibilityupdate, String catt_with_comp,
			String selectedSideBarValuesFinal) {
		String status = null;
		String updatedRow = row.replaceAll(",", "','");

		try {
			String number = null;

			List<loginmaster> englist = sessionFactory.getCurrentSession()
					.createQuery("from loginmaster where LOGINID = " + cr_no).list();
			for (loginmaster enggmaster : englist) {
				number = enggmaster.getPHONE();
			}
			//// //System.out.println("inside updateUserLoginMaster");
			Query query = sessionFactory.getCurrentSession().createQuery(
					"update loginmaster set SIDEBAR_SCOPE=:SIDEBAR_SCOPE,EMAIL = :E_MAIL,PHONE = :E_PHONE,USERNAME = :ENG_UNAME,CATEGORY=:CATEGORY,GROUP_NAME =:GROUP_NAME,VIP_LOGIN =:VIP_LOGIN,SUB_DEPARTMENT =:SUB_DEPARTMENT,LOGIN_SCOPE =:LOGIN_SCOPE,FULL_NAME = :E_NAME,ROLE_TYPE = :ROLE_TYPE,COMPANY = :E_COMPANY,BRANCH = :E_BRANCH,DEPARTMENT = :E_DEPARTMENT,LOCATION = :E_CATEGORY,LEVEL = :ENGLEVEL , DESIGNATION = :DESIGNATION ,VISIBILITY =:VISIBILITY,CATEGORY_WITH_COMPANY=:CATEGORY_WITH_COMPANY where LOGINID = :E_ID");

			query.setParameter("E_MAIL", mail);
			query.setParameter("E_PHONE", cno);
			query.setParameter("ENG_UNAME", user);
			query.setParameter("CATEGORY_WITH_COMPANY", catt_with_comp);
			query.setParameter("E_NAME", fname + " " + lname);

			query.setParameter("E_COMPANY", cname);
			query.setParameter("E_BRANCH", sname);
			query.setParameter("E_DEPARTMENT", dname);
			query.setParameter("E_CATEGORY", category);
			query.setParameter("ENGLEVEL", englevel);
			query.setParameter("E_ID", cr_no);
			query.setParameter("ROLE_TYPE", rtypeupdate);
			query.setParameter("LOGIN_SCOPE", updatedRow);
			query.setParameter("SUB_DEPARTMENT", subdnameupdate);
			query.setParameter("VIP_LOGIN", vipLogin);
			query.setParameter("GROUP_NAME", updategroup);
			query.setParameter("CATEGORY", updatecategory);
			query.setParameter("DESIGNATION", designation);
			query.setParameter("VISIBILITY", visibilityupdate);
			query.setParameter("SIDEBAR_SCOPE", selectedSideBarValuesFinal);
			int i = query.executeUpdate();

			//// //System.out.println("I VALUE ISD " + i);
			Query queryforadmange = sessionFactory.getCurrentSession()
					.createQuery("from AD_USER_MANAGE where COMPANY='" + cname + "' and  USERNAME='" + user + "'");

			List<AD_USER_MANAGE> listadmanage = queryforadmange.list();
			if (!listadmanage.isEmpty()) {
				Query updateadusermanage = sessionFactory.getCurrentSession().createQuery(
						"update AD_USER_MANAGE set USERTYPE=:USERTYPE where COMPANY=:COMPANY and USERNAME=:USERNAME");

				updateadusermanage.setParameter("USERTYPE", rtypeupdate);
				updateadusermanage.setParameter("COMPANY", cname);
				updateadusermanage.setParameter("USERNAME", user);

				int i2 = updateadusermanage.executeUpdate();

			}

			if (i == 0) {
				status = "error";
			} else {

				status = "success";
			}
//			sessionFactory.getCurrentSession()
//					.createQuery("update otp_check set CONTACT = '" + cno + "' where CONTACT = '" + number + "' and USER_TYPE = 'Engineer'")
//					.executeUpdate();
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;
//		return null;
	}

