	//04/09/2024
	public String DeleteLoginMasterData(int crno) {
	    String status = null;

	    try {
	    	List<loginmaster> list = sessionFactory.getCurrentSession()
	    		    .createQuery("from loginmaster where LOGINID = :crno")
	    		    .setParameter("crno", crno).list();
	        
	        if (list.isEmpty()) {
	            status = "error"; 
	            return status;
	        }

	        loginmaster recordToDelete = list.get(0);

	        
	        Deleted_Employees del=new Deleted_Employees();
	        del.setLOGINID(recordToDelete.getLOGINID());
	        del.setFULL_NAME(recordToDelete.getFULL_NAME());
	        del.setUSERNAME(recordToDelete.getUSERNAME());
	        del.setROLE_TYPE(recordToDelete.getROLE_TYPE());
	        del.setCOMPANY(recordToDelete.getCOMPANY());
	        del.setBRANCH(recordToDelete.getBRANCH());
	        del.setDEPARTMENT(recordToDelete.getDEPARTMENT());
	        del.setSUB_DEPARTMENT(recordToDelete.getSUB_DEPARTMENT());
	        del.setLOCATION(recordToDelete.getLOCATION());
	        del.setPASSWORD(recordToDelete.getPASSWORD());
	        del.setEMAIL(recordToDelete.getEMAIL());
	        del.setPHONE(recordToDelete.getPHONE());
	        del.setLOGIN_TYPE(recordToDelete.getLOGIN_TYPE());
	        del.setLEVEL(recordToDelete.getLEVEL());
	        del.setLOGIN_SCOPE(recordToDelete.getLOGIN_SCOPE());
	        del.setFIRST_LOGIN(recordToDelete.getFIRST_LOGIN());
	        del.setSECRETKEY(recordToDelete.getSECRETKEY());
	        del.setOTP(recordToDelete.getOTP());
	        del.setHEADER_COLOR(recordToDelete.getHEADER_COLOR());
	        del.setSIDEBAR_COLOR(recordToDelete.getSIDEBAR_COLOR());
	        del.setSMALL_FONT(recordToDelete.getSMALL_FONT());
	        del.setVIP_LOGIN(recordToDelete.getVIP_LOGIN());
	        del.setCATEGORY(recordToDelete.getCATEGORY());
	        del.setGROUP_NAME(recordToDelete.getGROUP_NAME());
	        del.setDESIGNATION(recordToDelete.getDESIGNATION());
	        del.setVISIBILITY(recordToDelete.getVISIBILITY());
	        del.setREPORTING_TO_MANAGER(recordToDelete.getREPORTING_TO_MANAGER());
	        del.setCATEGORY_WITH_COMPANY(recordToDelete.getCATEGORY_WITH_COMPANY());
	        del.setIDTYPE(recordToDelete.getIDTYPE());
	      
	        del.setSIDEBAR_SCOPE(recordToDelete.getSIDEBAR_SCOPE());
	        del.setGENDER(recordToDelete.getGENDER());
	        
	        getSession().save(del);
	      
	        int i = sessionFactory.getCurrentSession().createQuery("delete from loginmaster where LOGINID = :crno")
	                .setParameter("crno", crno)
	                .executeUpdate();

	        if (i == 0) {
	            status = "error"; 
	        } else {
	            status = "success";
	        }
	    } catch (Exception e) {
	        e.printStackTrace();
	        status = "error"; 
	    }

	    return status;
	}

	
