	@Override
	public String addTicketTag(String company, String ticketTag, String dname) {

		//// //System.out.println("Inside MasterDaoImpl addTicketTag method");
		String status = null;

		try {
			//// //System.out.println("Before Projection List ");
			Session s = getSession();
			//// //System.out.println("s =" + s);
			//// //System.out.println("category: " + company);
			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(ticket_tag_master.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				//// //System.out.println(" SRNO IS: " + srno1);

				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					//// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside addTicketTag");
			Query query = sessionFactory.getCurrentSession().createQuery(
					"from ticket_tag_master where (COMPANY=:COMPANY and DEPARTMENT=:DEPARTMENT) OR TICKET_TAG=:TICKET_TAG");
			query.setParameter("COMPANY", company);
			query.setParameter("DEPARTMENT", dname);
			query.setParameter("TICKET_TAG", ticketTag);

			List<ticket_tag_master> data = query.list();
			//// //System.out.println("checking ticket_tag_master table data:" +
			//// data.isEmpty());
			if (data != null && !data.isEmpty()) {
				status = "duplicate";
			} else {
				ticket_tag_master ticketTagMaster = new ticket_tag_master();

				ticketTagMaster.setSR_NO(srno);
				ticketTagMaster.setCOMPANY(company);
				ticketTagMaster.setDEPARTMENT(dname);
				ticketTagMaster.setTICKET_TAG(ticketTag);

				sessionFactory.getCurrentSession().save(ticketTagMaster);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;
	}

