	@Override
	public String updateTicketTagyMasterSave(String cnameupdate, int cr_no, String updatedname, String tagforsave) {

		//// //System.out.println("Inside MasterDaoImpl updateTicketTagyMasterSave
		//// method");
		String status = null;

		try {
			Query query = sessionFactory.getCurrentSession().createQuery(
					"from ticket_tag_master where (( COMPANY=:COMPANY and DEPARTMENT=:DEPARTMENT) OR TICKET_TAG=:TICKET_TAG ) AND SR_NO!=:SR_NO");
			query.setParameter("COMPANY", cnameupdate);
			query.setParameter("DEPARTMENT", updatedname);
			query.setParameter("TICKET_TAG", tagforsave);
			query.setParameter("SR_NO", cr_no);

			List<ticket_tag_master> data = query.list();
			//// //System.out.println("checking ticket_tag_master table data:" +
			//// data.isEmpty());
			if (data != null && !data.isEmpty()) {
				status = "duplicate";
			} else {

				//// //System.out.println("inside updateTicketTagyMasterSave");
				Query query2 = sessionFactory.getCurrentSession().createQuery(
						"update ticket_tag_master set COMPANY=:COMPANY , DEPARTMENT=:DEPARTMENT , TICKET_TAG=:TICKET_TAG where SR_NO=:SR_NO");

				query2.setParameter("COMPANY", cnameupdate);
				query2.setParameter("DEPARTMENT", updatedname);
				query2.setParameter("TICKET_TAG", tagforsave);
				query2.setParameter("SR_NO", cr_no);

				int i = query2.executeUpdate();

				if (i == 0) {
					status = "error";
				} else {

					status = "success";
				}
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;
	}

