	@Override
	public JSONArray getUserScopeForUpadte(String username, String E_id) {
		//// //System.out.println("Inside MasterDaoImpl getLoginMasterDetails method");

		JSONArray finalJSONArray = new JSONArray();
		JSONObject arrayobj = null;

//	String db_username = null;
//	String db_usertype = null;
		String loginScope = "";
		try {

			int LOGINID = Integer.parseInt(E_id);
			//// //System.out.println("LOGINID :::" + LOGINID);

			List<loginmaster> logindata = sessionFactory.getCurrentSession()
					.createQuery("from loginmaster where LOGINID=" + LOGINID + "").list();
			for (loginmaster lg : logindata) {
				loginScope = lg.getLOGIN_SCOPE();
			}
			//// //System.out.println("login scope from database:-" + loginScope);

			loginScope = loginScope.replaceAll("','", ",");
			loginScope = loginScope.replaceAll("'", "");
			loginScope = loginScope.replaceAll("'", "");
			loginScope = loginScope.replaceAll("T_COMPANY", "COMPANY");
			loginScope = loginScope.replaceAll("T_DEPARTMENT", "DEPARTMENT");
			loginScope = loginScope.replaceAll("T_BRANCH", "BRANCH");
			//// //System.out.println("loginScope1:- " + loginScope);
			loginScope = loginScope.replaceAll("COMPANY IN", "COMPANY");
			loginScope = loginScope.replaceAll("AND BRANCH IN", "BRANCH");
			loginScope = loginScope.replaceAll("AND DEPARTMENT IN", "DEPARTMENT");
			//// //System.out.println("loginScope2:- " + loginScope);
			// //////System.out.println("loginScope" + loginScope);
			String subString = loginScope.substring(0, loginScope.lastIndexOf(")"));
			//// //System.out.println("subString:- " + subString);
			String loginScopeArray[] = subString.split("\\) OR");
			for (int i = 0; i < loginScopeArray.length; i++) {
				String s = loginScopeArray[i];
				String ss = s.replaceFirst("\\(", "");
				//// //System.out.println("loginScopeArray:- " + ss);
				ss = ss.replaceAll("COMPANY", "");
				ss = ss.replaceFirst("\\(", "");
				ss = ss.replaceAll("\\) BRANCH \\(", " seperator ");
				ss = ss.replaceAll("\\) DEPARTMENT \\(", " seperator ");
				ss = ss.substring(0, ss.lastIndexOf(")"));

				//// //System.out.println("SSSSS:- " + ss);
				String lasteSeperatorArray[] = ss.split("seperator");
				String Company = lasteSeperatorArray[0];
				String Branch = lasteSeperatorArray[1];
				String Dept = lasteSeperatorArray[2];

				// //////System.out.println("Company:-" + Company);
				// //////System.out.println("Branch:-" + Branch);
				// //////System.out.println("Dept:-" + Dept);
				// //////System.out.println();

				arrayobj = new JSONObject();
				arrayobj.put("COMPANY", Company.trim());
				arrayobj.put("BRANCH", Branch.trim());
				arrayobj.put("DEPARTMENT", Dept.trim());
				finalJSONArray.put(arrayobj);

			}

		} catch (Exception e) {
			//// //System.out.println("Exception while seperating login scope:- " + e);
			e.printStackTrace();
			// TODO: handle exception
		}
		//// //System.out.println("getUserScopeForUpadte Dao Impl finalJSONArray:-" +
		//// finalJSONArray);

		return finalJSONArray;
	}

