	@Override
	public JSONArray getCategoryDetailsListforcatalogue(String company) {
		//// //System.out.println("Inside MasterDaoImpl
		//// getCategoryDetailsListforcatalogue
		//// method");
//		String db_cname = null;
		JSONArray array = null;
		JSONArray array1 = null;
		Set<String> listOfCategory = new HashSet<String>();

		try {

			array1 = new JSONArray();
			Query q = getSession().createQuery("select distinct CAT_NAME from categorymaster where COMPANY='" + company
					+ "' ORDER BY CAT_NAME asc");

			List Result = q.list();
			for (int i = 0; i < Result.size(); i++) {
				listOfCategory.add(Result.get(i).toString());
			}

			Query getcategory = sessionFactory.getCurrentSession()
					.createQuery("select distinct CAT_NAME from servicecataloguemaster where  COMPANY='" + company
							+ "' ORDER BY CAT_NAME asc");
			List getGL = getcategory.list();
			for (int i = 0; i < getGL.size(); i++) {
				listOfCategory.add(getGL.get(i).toString());
			}

			for (String str : listOfCategory) {
				array = new JSONArray();
				array.put(str);
				array1.put(array);
			}

		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return array1;
	}

