	@Override
	public String addNewCategory(String company, String category, String subcategory1, String subcategory2,
			String priority, String severity) {
		//// //System.out.println("Inside MasterDaoImpl addNewCategory method");
		String status = null;

		try {
			//// //System.out.println("company: " + company);
			//// //System.out.println("category: " + category);
			//// //System.out.println("subcategory1: " + subcategory1);
			//// //System.out.println("subcategory2: " + subcategory2);
			//// //System.out.println("priority: " + priority);
			//// //System.out.println("severity: " + severity);
			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(categorymaster.class)
						.setProjection(Projections.max("CAT_ID"));
				Integer srno1 = (Integer) crit.uniqueResult();

				//// //System.out.println(" SRNO IS: " + srno1);

				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					//// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside addNewCategory");
			Query query = sessionFactory.getCurrentSession().createQuery(
					"from categorymaster where COMPANY=:COMPANY and CAT_NAME=:CAT_NAME and SUB_CATEGORY1=:SUB_CATEGORY1 and SUB_CATEGORY2=:SUB_CATEGORY2 ");
			query.setParameter("COMPANY", company);
			query.setParameter("CAT_NAME", category);
			query.setParameter("SUB_CATEGORY1", subcategory1);
			query.setParameter("SUB_CATEGORY2", subcategory2);
//			query.setParameter("PRIORITY", priority);
//			query.setParameter("SEVERITY", severity);
//			and PRIORITY=:PRIORITY and SEVERITY=:SEVERITY
			categorymaster data = (categorymaster) query.uniqueResult();
			if (data != null) {
				// System.out.println("insert duplicate of catagory master" + data);
				status = "duplicate";
			} else {
				// System.out.println("inside the else ");
				categorymaster categorymaster1 = new categorymaster();

				categorymaster1.setCAT_ID(srno);
				categorymaster1.setCOMPANY(company);
				categorymaster1.setCAT_NAME(category);
				categorymaster1.setSUB_CATEGORY1(subcategory1);
				categorymaster1.setSUB_CATEGORY2(subcategory2);
				categorymaster1.setPRIORITY(priority);
				categorymaster1.setSEVERITY(severity);
				sessionFactory.getCurrentSession().save(categorymaster1);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;

	}

