	@Override
	public String addPrioritytemplate(String attribute1, String templatedeatil) {

		//// //System.out.println("Inside MasterDaoImpl addPrioritytemplate method");
		String status = null;

		try {
			//// //System.out.println("Before Projection List ");
			Session s = getSession();
			//// //System.out.println("s =" + s);
			//// //System.out.println("company: " + attribute1 + "companyemail: " +
			//// templatedeatil);
			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(prioritytemplatemaster.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				//// //System.out.println(" SRNO IS: " + srno1);

//				Query query1 =sessionFactory.getCurrentSession().createQuery("select max(USERID) FROM usermaster");
//				usermaster data1 = (usermaster) query1.uniqueResult();
//				//////System.out.println("data1......"+data1);
				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					//// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside addCompany");
			Query query = sessionFactory.getCurrentSession()
					.createQuery("from prioritytemplatemaster where NAME=:NAME");
			query.setParameter("NAME", templatedeatil);
			prioritytemplatemaster data = (prioritytemplatemaster) query.uniqueResult();
			if (data != null) {
				status = "duplicate";
			} else {
				prioritytemplatemaster company1 = new prioritytemplatemaster();

				company1.setSR_NO(srno);
				company1.setNAME(templatedeatil);
				company1.setATTRIBUTES(attribute1);

				sessionFactory.getCurrentSession().save(company1);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;
	}

