	@Override
	public JSONArray getSelfHelpScopeList() {
		//// //System.out.println("Inside MasterDaoImpl getSelfHelpScopeList method");

//		JSONArray array = null;
		JSONArray array1 = null;
		int srno[] = { 0 };
		String LoginUser = null;
		String loginRoleType = null;
		String loginusercompany = null;
		try {
			// Code for Login User
			ServletRequestAttributes requestAttributes = (ServletRequestAttributes) RequestContextHolder
					.getRequestAttributes();
			HttpSession session = requestAttributes.getRequest().getSession();
			LoginUser = session.getAttribute("username").toString();
			loginusercompany = session.getAttribute("companyname").toString();
			loginRoleType = session.getAttribute("role").toString();
			//// //System.out.println("username****" + LoginUser);
			//// //System.out.println("Login User Role****" + loginRoleType);

			Query userQuery = getSession().createQuery(
					"from loginmaster where USERNAME='" + LoginUser + "' and COMPANY='" + loginusercompany + "'");
			loginmaster loginUser = (loginmaster) userQuery.uniqueResult();
			//// //System.out.println("Login Scope is:");
			String loginScope = loginUser.getLOGIN_SCOPE();
			//// //System.out.println(loginScope);
			List<selfhelpmaster> dataList = null;
			String hql = null;
			if (loginRoleType.equals("User")) {
				hql = "from selfhelpmaster where T_COMPANY='" + loginUser.getCOMPANY() + "' and " + "T_BRANCH LIKE ('%"
						+ loginUser.getBRANCH() + "%') and T_DEPARTMENT like ('%" + loginUser.getDEPARTMENT() + "%')";

			} else {
				String fetchCompany = StringUtils.substringBetween(loginScope, "T_COMPANY IN ('", "')");
				String[] fetchBranch = StringUtils.substringBetween(loginScope, "T_BRANCH IN ('", "')").split("','");
				String[] fetchDepartment = StringUtils.substringBetween(loginScope, "T_DEPARTMENT IN ('", "')")
						.split("','");
//				String companylike = "";
				String branchlike = "";
				String deptlike = "";
//				for (String company : fetchCompany) {
//					companylike += "T_COMPANY LIKE('%"+ company + "%')";
//				}
				for (String branch : fetchBranch) {
					branchlike += "T_BRANCH LIKE('%" + branch + "%')";
				}
				for (String department : fetchDepartment) {
					deptlike += "T_DEPARTMENT LIKE('%" + department + "%')";
				}
//				companylike = companylike.replace(")T_COMPANY", ") OR T_COMPANY");
				branchlike = branchlike.replace(")T_BRANCH", ") OR T_BRANCH");
				deptlike = deptlike.replace(")T_DEPARTMENT", ") OR T_DEPARTMENT");
//				//////System.out.println("branchlike:" + branchlike);
//				//////System.out.println("deptlike:" + deptlike);
				hql = "from selfhelpmaster where (T_COMPANY IN ('" + fetchCompany + "')) and (" + branchlike + ") and ("
						+ deptlike + ")";
				//// //System.out.println("hql:" + hql);
			}
			Query query = sessionFactory.getCurrentSession().createQuery(hql);
			dataList = query.list();
			array1 = new JSONArray();
//			for (selfhelpmaster sourceDrive : dataList) { 
			array1 = dataList.stream().map(sourceDrive -> {
				srno[0] = srno[0] + 1;
				JSONArray array = new JSONArray();

				array.put("<button class='btn btn-sm btn-info' id='viewTicket'  name='Doem' onclick='viewDetails(\""
						+ sourceDrive.getSRNO() + "\" )'><i class='fa fa-eye'></i></button>");

				array.put(sourceDrive.getNAME());
				array.put(sourceDrive.getCATEGORY());
				array.put(sourceDrive.getPLATFORM());
				array.put(sourceDrive.getT_COMPANY());
				array.put(sourceDrive.getT_BRANCH());
				array.put(sourceDrive.getT_DEPARTMENT());
				array.put(sourceDrive.getUPLOADED_BY());
				array.put(sourceDrive.getUPLOAD_DATE());
				array.put(sourceDrive.getDOWNLOAD_COUNTER());

				return array;
//				array1.put(array);
			}).collect(JSONArray::new, JSONArray::put, JSONArray::put);
			//// //System.out.println("ARRAY OUTPUT: " + array1);
		} catch (Exception e) {
			e.printStackTrace();
		}
		return array1;
	}

	@Override
	public String addSelfHelpMaster(String company, String branch, String department, String name, String description,
			String category, String platform, MultipartFile empPic) {
		String status = "";
		String LoginUser = null;

		int id = 0;
		try {
			// Get Srno
			Criteria crit = sessionFactory.getCurrentSession().createCriteria(selfhelpmaster.class)
					.setProjection(Projections.max("SRNO"));
			Integer srno1 = (Integer) crit.uniqueResult();

			//// //System.out.println(" SRNO IS: " + srno1);

			if (srno1 != null) {
				id = srno1.intValue();
				id = id + 1;
				//// //System.out.println("IN IF SRNO IS: " + id);
			} else {
				id = 1;
				//// //System.out.println("IN ELSE SRNO IS: " + id);
			}

			// Add Current Date
			DateFormat dateFormat = null;
			dateFormat = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
			Date date = null;
			date = new Date();
			//// //System.out.println(dateFormat.format(date));
			String currenttime = dateFormat.format(date);

			// Add File
			String fileNameWithOutExt = FilenameUtils.removeExtension(empPic.getOriginalFilename());
			//// //System.out.println("FILENAME WITHOUT EXT: " + fileNameWithOutExt);
			DateTimeFormatter localdate = DateTimeFormatter.ofPattern("yyyy-MM-dd 'at' HH.mm.ss");
			LocalDateTime now = LocalDateTime.now();
			//// //System.out.println(localdate.format(now));
			String localDateNow = localdate.format(now);
//			String createnewfilename = UUID.randomUUID().toString();
			String createnewfilename = fileNameWithOutExt + " " + localDateNow + "_" + id;
			//// //System.out.println("createnewfilename***" + createnewfilename);
			String ext = "";
			String updatedFileName = null;
			try {
				String imagefilePath;
				imagefilePath = "C:\\ITHelpDesk\\";
				try {
					File file = new File("C:\\ITHelpDesk\\");
					if (!file.exists()) {
						if (file.mkdir()) {
							//// //System.out.println("Directory is created!");
						} else {
							//// //System.out.println("Failed to create directory!");
						}
					}
				} catch (Exception e) {
					//// //System.out.println("directory create exception" + e);
				}

//	            File uploadedFile =  empPic;
				File uploadedFile = new File(empPic.getOriginalFilename());
				uploadedFile.createNewFile();
				FileOutputStream fos = new FileOutputStream(uploadedFile);
				fos.write(empPic.getBytes());
				fos.close();
				//// //System.out.println("uploadedFile::::" + uploadedFile);
				String fileName = empPic.getOriginalFilename();
				//// //System.out.println("fileName::::" + fileName);
				ext = FilenameUtils.getExtension(fileName);
				//// //System.out.println("file_extension::::" + ext);
				// File destFile = new File(imagefilePath + File.separator + fileName);
				File destFile = new File(imagefilePath + File.separator + createnewfilename + "." + ext);
				//// //System.out.println("destFile........" + destFile);
				// //////System.out.println("File........" + imagefilePath + File.separator +
				// fileName);
				//// //System.out.println("File........" + imagefilePath + File.separator +
				//// createnewfilename + "." + ext);
				updatedFileName = createnewfilename + "." + ext;
				//// //System.out.println("UPDATED FILE NAME: " + updatedFileName);

				try {
					FileUtils.copyFile(uploadedFile, destFile);
					File filee = new File(imagefilePath + File.separator + createnewfilename + "." + ext);
					FileInputStream fis = new FileInputStream(filee);
				} catch (IOException ex) {
					//// //System.out.println("Could not copy file " + fileName);
					status = "error";
					ex.printStackTrace();
				}
			} catch (Exception e) {
				//// //System.out.println("directory create exception" + e);
			}
			// Get Login User
			ServletRequestAttributes requestAttributes = (ServletRequestAttributes) RequestContextHolder
					.getRequestAttributes();
			HttpSession session = requestAttributes.getRequest().getSession();
			LoginUser = session.getAttribute("username").toString();
			//// //System.out.println("username****" + LoginUser);
			// Add Self Help Master
			String finalBranch = branch.replace(",", "%");
			String finalDepartment = department.replace(",", "%");
			Query query = getSession().createQuery("from selfhelpmaster where T_COMPANY=:COMPANY and T_BRANCH like ('%"
					+ finalBranch + "%') and " + "T_DEPARTMENT like ('%" + finalDepartment + "%') and NAME=:NAME");
			query.setParameter("COMPANY", company);
			query.setParameter("NAME", name);
			selfhelpmaster data = (selfhelpmaster) query.uniqueResult();
			if (data != null) {
				status = "duplicate";
			} else {
				selfhelpmaster selfhelp = new selfhelpmaster();
				selfhelp.setSRNO(id);
				selfhelp.setT_COMPANY(company);
				selfhelp.setT_BRANCH(branch);
				selfhelp.setT_DEPARTMENT(department);
				selfhelp.setNAME(name);
				selfhelp.setDESCRIPTION(description);
				selfhelp.setCATEGORY(category);
				selfhelp.setPLATFORM(platform);
				selfhelp.setUPLOAD_DATE(currenttime);
				selfhelp.setUPLOADED_BY(LoginUser);
				selfhelp.setATTACH_NAME(updatedFileName);
				selfhelp.setDOWNLOAD_COUNTER(0);
				getSession().save(selfhelp);
				status = "success";
			}

		} catch (Exception e) {
			e.printStackTrace();
		}
		return status;
	}

