	@Override
	public String addgroup(String group, String company) {

		//// //System.out.println("Inside MasterDaoImpl addgroup method");
		String status = null;

		try {
			//// //System.out.println("Before Projection List ");
			Session s = getSession();
			//// //System.out.println("s =" + s);
			//// //System.out.println("group: " + group);
			//// //System.out.println("company: " + company);
			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(Group_master2.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				//// //System.out.println(" SRNO IS: " + srno1);

//				Query query1 =sessionFactory.getCurrentSession().createQuery("select max(USERID) FROM usermaster");
//				usermaster data1 = (usermaster) query1.uniqueResult();
//				//////System.out.println("data1......"+data1);
				if (srno1 != null) {
					srno = srno1.intValue();
					srno = srno + 1;
					//// //System.out.println("IN IF SRNO IS: " + srno);
				} else {
					srno = 1;
					//// //System.out.println("IN ELSE SRNO IS: " + srno);
				}
			} catch (Exception e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				//// //System.out.println(e);
			}

			//// //System.out.println("inside addgroup");
			Query query = sessionFactory.getCurrentSession()
					.createQuery("from Group_master2 where GROUP_NAME=:GROUP_NAME");
			query.setParameter("GROUP_NAME", group);
			// query.setParameter("COMPANY", company);

			Group_master2 data = (Group_master2) query.uniqueResult();

			if (data != null) {
				status = "duplicate";
			} else {
				Group_master2 group1 = new Group_master2();

				group1.setSR_NO(srno);
				group1.setGROUP_NAME(group);
				group1.setCOMPANY(company);
				sessionFactory.getCurrentSession().save(group1);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;
	}

