	@Override
	public JSONArray ViewAutoAssignTicket(String userlist) {

		// ----------------------------------------------------------------
		//// //System.out.println("Inside auto_close_details addUserDetails method");
		JSONArray array = null;

		JSONArray array1 = null;
		int srno = 0;
//		String db_username = null;
//		String db_usertype = null;

		try {
			//// //System.out.println("Before Projection List auto_close_details ");
			Session s = getSession();
			//// //System.out.println("s =" + s);
			long totalSeconds = 0;

			List<AUTO_ASSIGN_TICKET> dataList = sessionFactory.getCurrentSession()
					.createQuery("from AUTO_ASSIGN_TICKET").list();
//			query.setParameter("c", cname);
			array1 = new JSONArray();
			for (AUTO_ASSIGN_TICKET a : dataList) {
				srno = srno + 1;
				// //////System.out.println("array = " + sourceDrive.getNAME());
				array = new JSONArray();

				array.put(srno);
				array.put("<button class='btn btn-danger' id='Delete'  name='Delete' onclick='DeleteAutoAssign(\""
						+ a.getSR_NO() + "\" )'><i class='fa fa-trash'></i></button>");
				array.put(a.getCOMPANY());
				array.put(a.getPRIORITY());
				array.put(a.getSEVERITY());
				array.put(a.getCATEGORY());

				totalSeconds = Long.parseLong(a.getASSIGN_TIME());
				int day = (int) TimeUnit.SECONDS.toDays(totalSeconds);
				long hours = TimeUnit.SECONDS.toHours(totalSeconds) - (day * 24);
				long minute = TimeUnit.SECONDS.toMinutes(totalSeconds) - (TimeUnit.SECONDS.toHours(totalSeconds) * 60);
				long second = TimeUnit.SECONDS.toSeconds(totalSeconds)
						- (TimeUnit.SECONDS.toMinutes(totalSeconds) * 60);

				array.put(day);
				array.put(hours);
				array.put(minute);
				array.put(second);

				array1.put(array);
			}

		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		//// //System.out.println("Array put===" + array1);
		return array1;
	}

