	@Override
	public String updateCompositeMaster(int srNo, String company, String branch, String location, String dept,
			String subDept) {
		String status = null;
		try {

			Query query2 = getSession().createQuery("from compositemaster where COMPANY='" + company + "' AND BRANCH='"
					+ branch + "'" + " and LOCATION='" + location + "' and DEPARTMENT='" + dept
					+ "' and SUB_DEPARTMENT='" + subDept + "'");
			List<compositemaster> data1 = query2.list();
			//// //System.out.println("data:123" + data1);
			if (!data1.isEmpty()) {
				status = "duplicate";
			} else {

				//// //System.out.println("inside UpdateSLADetails");
				Query query = getSession().createQuery("update compositemaster set COMPANY ='" + company + "',BRANCH='"
						+ branch + "',LOCATION='" + location + "',DEPARTMENT='" + dept + "'" + ",SUB_DEPARTMENT='"
						+ subDept + "' where PCOM_ID='" + srNo + "'");
				int i = query.executeUpdate();

				if (i == 0) {
					status = "error";
				} else {

					status = "success";
				}

			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;

	}

