	@Override
	public String updatemailtemplate(String srno, String st, String subject, String mailbody, String company,
			String emailTrigger, String ticketType, String mailfooter) {
		String status = null;

		int srNO = Integer.parseInt(srno);

		//// //System.out.println("inside adduser status====" + st);
		//// //System.out.println("ticket Type ======" + ticketType);
		Query query = sessionFactory.getCurrentSession().createQuery("from ADD_MAIL_TEMPLATE where COMPANY='" + company
				+ "' and STATUS='" + st + "' and  TICKET_TYPE='" + ticketType + "' and SR_NO!='" + srNO + "'");

		List data = query.list();

		if (data.isEmpty()) {
			String hql = "UPDATE ADD_MAIL_TEMPLATE set SUBJECT= :SUBB,MAILBODY=:MAILBODYY,COMPANY=:COMPANY,EMAIL_TRIGGER=:EMAIL_TRIGGER,TICKET_TYPE=:TICKET_TYPE,STATUS=:STATUSS,MAIL_FOOTER=:MAIL_FOOTER WHERE SR_NO='"
					+ srNO + "'";

			Query query1 = sessionFactory.getCurrentSession().createQuery(hql);
			query1.setParameter("SUBB", subject);
			query1.setParameter("MAILBODYY", mailbody);
			query1.setParameter("COMPANY", company);
			query1.setParameter("EMAIL_TRIGGER", emailTrigger);
			query1.setParameter("TICKET_TYPE", ticketType);
			query1.setParameter("MAIL_FOOTER", mailfooter);

			query1.setParameter("STATUSS", st);

			int i = query1.executeUpdate();
			//// //System.out.println("update subcat master" + i);
			if (i > 0) {
				status = "success";

			} else {
				status = "error";
			}

		} else {
			status = "duplicate";
		}

		return status;
	}

