			String hql = "UPDATE sla_week_scheduler set MONDAY_START_TIME=:MONDAY_START_TIME, MONDAY_END_TIME=:MONDAY_END_TIME, TUESDAY_START_TIME=:TUESDAY_START_TIME, TUESDAY_END_TIME=:TUESDAY_END_TIME, WEDNESDAY_START_TIME=:WEDNESDAY_START_TIME, WEDNESDAY_END_TIME=:WEDNESDAY_END_TIME, THURSDAY_START_TIME=:THURSDAY_START_TIME, THURSDAY_END_TIME=:THURSDAY_END_TIME, FRIDAY_START_TIME=:FRIDAY_START_TIME, FRIDAY_END_TIME=:FRIDAY_END_TIME, SATURDAY_START_TIME=:SATURDAY_START_TIME, SATURDAY_END_TIME=:SATURDAY_END_TIME, SUNDAY_START_TIME=:SUNDAY_START_TIME, SUNDAY_END_TIME=:SUNDAY_END_TIME,MONDAY_ELAPSTIME=:MONDAY_ELAPSTIME,THURSDAY_ELAPSTIME=:THURSDAY_ELAPSTIME,TUESDAY_ELAPSTIME=:TUESDAY_ELAPSTIME,WEDNESDAY_ELAPSTIME=:WEDNESDAY_ELAPSTIME,FRIDAY_ELAPSTIME=:FRIDAY_ELAPSTIME,SATURDAY_ELAPSTIME=:SATURDAY_ELAPSTIME,SUNDAY_ELAPSTIME=:SUNDAY_ELAPSTIME  WHERE COMPANY_NAME=:COMPANY_NAME";

