	@Override
	public String SaveSoftwareDetails(String sname, String productcode, String fromdate, String checkbox, Float scost,
			String rperiod) {
		String status = "";
		try {

			int srno = 0;
			try {
				Criteria setProjection = sessionFactory.getCurrentSession().createCriteria(SOFTWARE.class)
						.setProjection(Projections.max("SRNO"));
				Integer uniqueResult = (Integer) setProjection.uniqueResult();
				if (uniqueResult != 0) {
					srno = srno + uniqueResult.intValue();
					srno = srno + 1;
				} else {
					srno = 1;
				}
				List list = sessionFactory.getCurrentSession()
						.createQuery("from SOFTWARE where S_COST='" + scost + "'and S_NAME='" + sname
								+ "'and S_PERIOD='" + rperiod + "'and ACTIVE_CONDITION='" + checkbox
								+ "'and FROM_DATE='" + fromdate + "'and PRODUCT_CODE='" + productcode + "'")
						.list();
//				List<SOFTWARE> soft=lis
				if (list.isEmpty()) {
					SOFTWARE sft = new SOFTWARE();
					sft.setS_NAME(sname);
					sft.setACTIVE_CONDITION(checkbox);
					sft.setFROM_DATE(fromdate);
					sft.setS_COST(scost);
					sft.setSRNO(srno);
					sft.setS_PERIOD(rperiod);
					sessionFactory.getCurrentSession().save(sft);
					status = "success";
				} else {
					status = "duplicate";
				}

			} catch (Exception e) {
				// TODO: handle exception
			}

		} catch (Exception e) {
			// TODO: handle exception
		}

		return status;

	}

