	@Override
	public String UpdateSoftwareDetails(String sname, String productcode, String fromdate, String checkbox,
			String scost, String rperiod, int srno) {
		String status = "";
		Query checkrecord = sessionFactory.getCurrentSession()
				.createQuery("from SOFTWARE where S_COST='" + scost + "'and S_NAME='" + sname + "'and S_PERIOD='"
						+ rperiod + "' and ACTIVE_CONDITION='" + checkbox + "' and FROM_DATE='" + fromdate
						+ "' and PRODUCT_CODE='" + productcode + "'");
		List<SOFTWARE> sft = checkrecord.list();
		if (sft.isEmpty()) {
			int executeUpdate = sessionFactory.getCurrentSession()
					.createQuery("update SOFTWARE set S_COST='" + scost + "', S_NAME='" + sname + "', S_PERIOD='"
							+ rperiod + "' , ACTIVE_CONDITION='" + checkbox + "' , FROM_DATE='" + fromdate
							+ "' , PRODUCT_CODE='" + productcode + "' where SRNO='" + srno + "'")
					.executeUpdate();
			if (executeUpdate > 0) {
				status = "success";
			} else {
				status = "error";
			}
		} else {
			status = "duplicate";
		}

		return status;
	}

