	@Override
	public JSONArray getScopeBasedCategory() {

		//// //System.out.println("Inside MasterDaoImpl getCompany method");
		String db_sname = null;
		JSONArray array = null;
		JSONArray array1 = new JSONArray();
		String LoginScop = null;

		try {
			ServletRequestAttributes requestAttributes = (ServletRequestAttributes) RequestContextHolder
					.getRequestAttributes();
			HttpSession session = requestAttributes.getRequest().getSession();

			LoginScop = session.getAttribute("loginscope").toString();
			String[] SplitArray = LoginScop.split("OR");
			/////// ITERATE STRING FOR 'OR' KEYWORD ///////////
			TreeSet<String> ts1 = new TreeSet<String>();
			for (String splitString : SplitArray) {
				//// //System.out.println("SPLIT STRING FOUND: " + splitString);
				String fetchCompany = StringUtils.substringBetween(splitString, "T_COMPANY IN ('", "')");
				String fetchBranch = StringUtils.substringBetween(splitString, "T_BRANCH IN ('", "')");
				String fetchDepartment = StringUtils.substringBetween(splitString, "T_DEPARTMENT IN ('", "')");
				ts1.add(fetchCompany);
			}
			List<String> list = new ArrayList<>(ts1);
			String string = "";
//	 ts1.forEach(a->{
//		String str =a.toString();
//		string=str;
//	 });	
			for (int i = 0; i < ts1.size(); i++) {
				String comp = list.get(i);
				if (string.equals("")) {
					string = comp;
				} else {
					string = string + "," + comp;
				}
			}
//			 System.out.println("sdfffffffffffff"+string);			 
			String str1 = string;
			String company = str1.replaceAll(",", "','");
			Query createQuery = sessionFactory.getCurrentSession()
					.createQuery("select distinct CAT_NAME from categorymaster where COMPANY in('" + company
							+ "') order by CAT_NAME asc");
			System.out.println("select distinct CAT_NAME from categorymaster where COMPANY in('" + company
					+ "') order by CAT_NAME asc");
			List<String> listOfCategroy = createQuery.list();
			for (Object str : listOfCategroy) {
				array = new JSONArray();
				array.put(str.toString());
				array1.put(array);
			}
		} catch (Exception e) {
			e.printStackTrace();
		} finally {
		}

		return array1;

	}

