	@Override
	public String getcompositeBulkUploadFile() {
		// TODO Auto-generated method stub
		//// System.out.println("INSIDE getUserBulkUploadFile DAOIMPL");
		String fileName = "BulkUploadHelpdeskComposite.xlsx";
		try {
			XSSFWorkbook workbookBase = new XSSFWorkbook();
			XSSFSheet baseSheet = workbookBase.createSheet("BulkUploadHelpdeskComposite");

			Map<String, Object[]> dataFirstRow = new HashMap<String, Object[]>();
			dataFirstRow.put("0", new Object[] { "COMPANY", "BRANCH", "DEPARTMENT", "SUB_DEPARTMENT", "LOCATION" });

			dataFirstRow.put("1", new Object[] { "NA", "NA", "NA", "NA", "NA" });
			Set<String> keyset = dataFirstRow.keySet();
//					Object[] objArr = dataFirstRow.get("1");
			int rownum = 0;
			/*
			 * XSSFCellStyle style1 = workbookBase.createCellStyle(); XSSFColor yellowColor
			 * = new XSSFColor(Color.YELLOW); style1.setFillForegroundColor(yellowColor);
			 * style1.setBorderBottom(XSSFCellStyle.BORDER_THIN);
			 * style1.setBorderTop(XSSFCellStyle.BORDER_THIN);
			 * style1.setBorderLeft(XSSFCellStyle.BORDER_THIN);
			 * style1.setBorderRight(XSSFCellStyle.BORDER_THIN);
			 */

			CellStyle style = workbookBase.createCellStyle();
			Font font = workbookBase.createFont();
			font.setColor(IndexedColors.RED.getIndex());
			style.setFont(font);

			for (String key : keyset) {
				// this creates a new row in the sheet
				Row row = baseSheet.createRow(rownum++);
				Object[] objArr = dataFirstRow.get(key);
				int cellnum = 0;

				for (Object obj : objArr) {
					// this line creates a cell in the next column of that row
					Cell cell = row.createCell(cellnum++);
//							if (obj instanceof String) {
					if (obj.toString().equals("COMPANY")) {
						cell.setCellValue((String) obj);
						cell.setCellStyle(style);
					} else if (obj.toString().equals("BRANCH")) {
						cell.setCellValue((String) obj);
						cell.setCellStyle(style);
					} else if (obj.toString().equals("DEPARTMENT")) {
						cell.setCellValue((String) obj);
						cell.setCellStyle(style);
					} else if (obj.toString().equals("SUB_DEPARTMENT")) {
						cell.setCellValue((String) obj);
						cell.setCellStyle(style);
					} else if (obj.toString().equals("LOCATION")) {
						cell.setCellValue((String) obj);
						cell.setCellStyle(style);
					}
//							else {
//								cell.setCellValue((String) obj);
//							}
//							} else if (obj instanceof Integer) {
//								cell.setCellValue((Integer) obj);
//							}
				}
			}

			FileOutputStream out = new FileOutputStream(new File("E:\\BulkUploadHelpdeskComposite.xlsx"));
			workbookBase.write(out);
			out.close();
			System.out.println("BulkUploadHelpdeskComposite.xlsx file created sucessfully");

		} catch (Exception e) {
			System.out.println("Error at BulkUploadHelpdeskComposite():" + e.getMessage());
			e.printStackTrace();
		}
		return fileName;
	}

