	@Override
	public String deleteProductMaster(String engType, String engineercost, String implementorCosttotal,
			String implemetationcost, String typepercentage, String costdata, String totalothercost) {

		String status = null;
		try {
			Session s = getSession();
			int srno = 0;

			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(OtherCost.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				if (srno1 != null) {
					srno = srno1.intValue() + 1;

				} else {
					srno = 1;
				}
			} catch (Exception e) {

				e.printStackTrace();
			}

			Query query = sessionFactory.getCurrentSession().createQuery(
					"from OtherCost where ENGINEERTYPE=:ENGINEERTYPE AND ENGINEERCOST=:ENGINEERCOST AND IMPLEMENTORCOST=:IMPLEMENTORCOST AND  IMPLEMENTCOST=:IMPLEMENTCOST AND TYPEPERCENTAGE=:TYPEPERCENTAGE AND COSTDATA=:COSTDATA AND TOTALOTHERCOST=:TOTALOTHERCOST");
			query.setParameter("ENGINEERTYPE", engType);
			query.setParameter("ENGINEERCOST", engineercost);
			query.setParameter("IMPLEMENTORCOST", implementorCosttotal);
			query.setParameter("IMPLEMENTCOST", implemetationcost);
			query.setParameter("TYPEPERCENTAGE", typepercentage);
			query.setParameter("COSTDATA", costdata);
			query.setParameter("TOTALOTHERCOST", implementorCosttotal);
			List data = query.list();

			if (!data.isEmpty()) {
				status = "duplicate";
			} else {
				OtherCost othercost = new OtherCost();
				othercost.setSR_NO(srno);
				othercost.setENGINEERTYPE(engType);
				othercost.setENGINEERCOST(engineercost);
				othercost.setIMPLEMENTORCOST(implementorCosttotal);
				othercost.setIMPLEMENTCOST(implemetationcost);
				othercost.setTYPEPERCENTAGE(typepercentage);
				othercost.setCOSTDATA(costdata);
				othercost.setTOTALOTHERCOST(totalothercost);
				getSession().save(othercost);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		return status;
	}

