	private static PdfPCell createPdfPCell(String value) {
		PdfPCell cell = new PdfPCell(new Phrase(value));
		cell.setVerticalAlignment(Element.ALIGN_MIDDLE);
		return cell;
	}

	private static PdfPCell createPdfPCell(double value) {
		PdfPCell cell = new PdfPCell(new Phrase(String.valueOf(value)));
		cell.setVerticalAlignment(Element.ALIGN_MIDDLE);
		return cell;
	}

	private static void addTableHeaderSubsAndPerp(PdfPTable table, String proposaltype,
		 String productsuitdetails,String subscriptionANDperpetualYear) {
		

if (proposaltype.equalsIgnoreCase("Subscription & Perpetual")) {
			
			System.out.println("Inside table header Subscription & Perpetual perpetual 3 year:");
			
			String headerYear ="";
			
			if(subscriptionANDperpetualYear.equalsIgnoreCase("Annual Price")) {
				
				headerYear ="Total Price including 1 year warranty";
				
			}else if(subscriptionANDperpetualYear.equalsIgnoreCase("3 Year Price")) {
				
				headerYear ="Total Price including 3 year warranty";
			}

			Stream.of("Sr. No.", "Product Name", "Description", "Qty", "Unit Rate",
					headerYear).forEach(columnTitle -> {
						PdfPCell header = new PdfPCell();

						header.setBackgroundColor(BaseColor.LIGHT_GRAY);
						// header.setBorderWidth(2);

						header.setPadding(5f); // Add cell padding
						header.setVerticalAlignment(Element.ALIGN_MIDDLE);

						Paragraph paragraph = new Paragraph(columnTitle);
						paragraph.setAlignment(Element.ALIGN_CENTER); // Align text to the center
						paragraph.getFont().setSize(14); // Set font size
						paragraph.setSpacingAfter(8); // Add spacing after the text
						header.addElement(paragraph);

						header.setPhrase(new Phrase(columnTitle));
						table.addCell(header);
					});

			float[] columnWidths = new float[] { 2, 5, 4, 2, 3, 5 };
			try {
				table.setWidths(columnWidths);
			} catch (DocumentException e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
			}

			table.setWidthPercentage(98f); // Make the table span the full width
			table.setSpacingBefore(9f); // Add space before the table

			
		}

	
	}
	
