	@Override
	public String setProposalMaster(String proposalName) {
		String status = null;

		try {
			// Adding Sr_no
			Criteria crit = sessionFactory.getCurrentSession().createCriteria(ProposalMaster.class)
					.setProjection(Projections.max("SR_NO"));
			Integer srno1 = (Integer) crit.uniqueResult();
			int srno = 0;
			//// //System.out.println(" SRNO IS: " + srno1);

			if (srno1 != null) {
				srno = srno1.intValue();
				srno = srno + 1;
				//// //System.out.println("IN IF SRNO IS: " + srno);
			} else {
				srno = 1;

			}

			Query query = getSession().createQuery("from ProposalMaster where  proposalName=:proposalName");

			query.setParameter("proposalName", proposalName);

			ProposalMaster data = (ProposalMaster) query.uniqueResult(); //// //System.out.println("data:" + data);

			if (data != null) {
				status = "duplicate";
			} else {
				ProposalMaster proponmaster = new ProposalMaster();

				proponmaster.setSR_NO(srno);

				proponmaster.setProposalName(proposalName);

				getSession().save(proponmaster);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		return status;
	}

