	private String RFValidateFormatcomposite(String filezz) {
		String result = "false";
		XSSFWorkbook workbook;
		try {
			FileInputStream file = new FileInputStream(filezz);
			workbook = new XSSFWorkbook(file);
			XSSFSheet sheet = workbook.getSheetAt(0);
			XSSFRow row = sheet.getRow(0);

			if (row != null) {
				Iterator<Cell> it1 = row.cellIterator();
				ArrayList<String> actualHeaders = new ArrayList<>();

				while (it1.hasNext()) {
					actualHeaders.add(it1.next().toString());
				}

				System.out.println("All RFheaders are " + actualHeaders);
				System.out.println("Total number of columns are " + actualHeaders.size());

				ArrayList<String> expectedHeaders = new ArrayList<>(Arrays.asList("CATEGORY_TYPE", "COMPANY",
						"REGISTRATION_NO", "ADDRESS", "PERSON_NAME", "MOBILE_NO", "TELEPHONE_NO", "CEO_EMAIL_ID",
						"SALES_EMAIL_ID", "SUPPORT_EMAIL_ID", "EMAIL_ID_CONTACT_PERSON", "EMAIL_ID_OFFICE", "CITY",
						"DISTRICT", "STATE", "PIN_CODE", "COUNTRY", "WEBSITE", "PAN_NO", "OWNERSHIP_TYPE",
						"SCALE_OF_COMPANY", "GSTIN", "NAME_OF_THE_PERSON", "DESIGNATION_NO", "EXPERIENCE",
						"DATE_OF_BUSINESS", "CURRENCY", "YEAR1", "YEAR2", "YEAR3", "AMOUNT1", "AMOUNT2", "AMOUNT3",
						"REGISTERED_IN_GEM", "REGISTERED_IN_MSMED", "EM_NO", "INCORPORATION_CERTIFICATE", "PAN_CARD",
						"GST_CERTIFICATE", "MSMED", "CANCELLED_CHEQUE", "BS_AND_P_L", "MSMED_DOCUMENTS",
						"MSMED_REGISTERTYPE", "AUTHORIZER", "SALES_MANAGER", "CP_FILE", "PO_FILE", "STATUS",
						"SUBMITTED_BY", "SUBMITTED_DATE", "APPROVED_BY", "APPROVED_DATE", "REJECTED_BY",
						"REJECTED_DATE"));

				// Check if predefined headers match actual headers
				if (actualHeaders.containsAll(expectedHeaders) && expectedHeaders.containsAll(actualHeaders)) {
					System.out.println("Headers match.");
					result = "true";
				} else {
					System.out.println("Headers do not match.");
				}
			} else {
				System.out.println("No header row found in the Excel sheet.");
			}
		} catch (Exception e) {
			e.printStackTrace();
			System.err.println("Error while processing the Excel file: " + e.getMessage());
			result = "false"; // Set the result to "false" to indicate an error.
		}

		return result;

	}

