		@Override
		public JSONArray generateEnvkey(String productSuitNameList,String proposalId) {


			JSONArray array1 = new JSONArray();

		String proposal_id = proposalId;
//		String proposal_id_input ="";
		


		String product_suit_name = null;
		
		StringBuilder environmentKey = new StringBuilder();
		
		String proposal_id_input = null;

			try {
				
				 //////// Generating Environment Key  Adn
				
				 String generatedKey = generateKey(productSuitNameList);

		    
		        if (proposal_id.contains("-")) {
		           
		            String[] parts = proposal_id.split("-");
		            
		       
		            try {
		                int number = Integer.parseInt(parts[1]);
		                
		                // Replace the hyphen with an empty string and concatenate the parts
		                String outputString = parts[0] + (number < 10 ? "0" : "") + parts[1];
//		                System.out.println("Input String: " + proposal_id);
//		                System.out.println("Output String: " + outputString);
		                
		                proposal_id_input = outputString;
		                
		            } catch (NumberFormatException e) {
		                
		            	// If the second part is not a valid number, print the original string
	                   proposal_id_input = proposal_id;
		            }
		            
		        } else {
		            // If there is no hyphen, just print the original string
		            proposal_id_input = proposal_id;
		        }
		        
		        Random random = new Random();

		        // Generate a random 4-digit number
		        int randomNumber = 1000 + random.nextInt(9000);

		        // Display the generated number
		        System.out.println("Random 4-digit number: " + randomNumber);
		        
		        environmentKey.append(generatedKey);
		        environmentKey.append("-");
		        environmentKey.append(proposal_id_input);
		        environmentKey.append("-");
		        environmentKey.append(randomNumber);
				
				
			} catch (Exception e) {
				System.out.println("Exception...  " + e);
				e.printStackTrace();
			}

			array1.put(environmentKey);
			System.out.println("environmentKey...  " + environmentKey);
			
			
		
			System.out.println("final value Adn " + array1);
			return array1;

		
		}
