		@Override
		public String saveupload(MultipartFile[] manualProposalFile,String uname,String crno,String tid) {
			// TODO Auto-generated method stub
			System.out.println("uname%%%%%%%%%%%%%%%%%SSSS"+uname);
			System.out.println("crno"+crno);
			System.out.println("tid"+tid);
			
			long maProSize = 0;
			for (MultipartFile ppf : manualProposalFile) {
				maProSize = ppf.getSize();
			}
			
			String imagefilePath = "C:\\Uploaded License\\";
			File dir = new File(imagefilePath);

			if (!dir.exists())
				dir.mkdirs();
			
			String manualProposalFile1 = "";
			if (maProSize > 0) {
				System.out.println("Po upload File attachement");

				try {
					double beforeFileSize[] = new double[manualProposalFile.length];
					byte[] bytes1 = new byte[manualProposalFile.length];

					List<byte[]> bytes = new ArrayList<byte[]>();

					for (int i = 0; i < manualProposalFile.length; i++) {

						String fileName1 = manualProposalFile[i].getOriginalFilename();
					
						String fileName = fileName1.replaceAll(" ", "_");
						
						beforeFileSize[i] = (double) manualProposalFile[i].getSize();
						bytes.add(manualProposalFile[i].getBytes());
						String name = FilenameUtils.removeExtension(fileName);
						
						String newfileName = name;
						
						String ext = FilenameUtils.getExtension(fileName);
						
						manualProposalFile1 = newfileName + "." + ext;
						System.out.println("BugName fileName>>>>>" + manualProposalFile1);

					}

					
//					VELOX_LICENSE license = new VELOX_LICENSE();
//					license.setSR_NO(Integer.parseInt(tid));
//					license.setVP_ID(crno);
//					license.setUploadfile(manualProposalFile1);
				try {
					String hql = "UPDATE VELOX_LICENSE set uploadfile=:EMAIL where VP_ID=:crno and SR_NO=:SRNO ";
					
					Query query1 = sessionFactory.getCurrentSession().createQuery(hql);
					query1.setParameter("EMAIL", manualProposalFile1);
					query1.setParameter("crno", crno);
					query1.setParameter("SRNO", Integer.parseInt(tid));
			
					int i = query1.executeUpdate();
					String result;
					//// //System.out.println("update AD_USER_MANAGE master" + i);
					if (i > 0) {
						result = "success";

					} else {
						result = "failed";
					}
				} catch (Exception e) {
					// TODO: handle exception
				}	
					
					
//					sessionFactory.getCurrentSession().save(license);
					
					for (int i = 0; i < manualProposalFile.length; i++) {
						File serverFile = new File(dir.getAbsolutePath() + File.separator + manualProposalFile1);
						BufferedOutputStream stream = new BufferedOutputStream(new FileOutputStream(serverFile));
						stream.write(bytes.get(i));
						stream.close();

						System.out.println("Server File1 Location=" + serverFile.getAbsolutePath());
					}

				} catch (Exception e1) {
					System.out.println("exce: " + e1);
				}
			}
			
			return "success";
		}

		
