		@Override
		public String saveTlMaster(String productsuit, String productname, String unit, String implementerName,
				String tlname, String developer, String customerName) {
			String status = null;
			try {
				Session s = getSession();
				int srno = 0;

				String implementorUsername = "";
				try {
					Criteria crit = sessionFactory.getCurrentSession().createCriteria(TlMaster.class)
							.setProjection(Projections.max("SR_NO"));
					Integer srno1 = (Integer) crit.uniqueResult();

					if (srno1 != null) {
						srno = srno1.intValue() + 1;

					} else {
						srno = 1;
					}
				} catch (Exception e) {

					e.printStackTrace();
				}



				Query query = sessionFactory.getCurrentSession().createQuery(
						"from TlMaster where PRODUCT_SUIT=:PRODUCT_SUIT AND SECURITY_SOLTION=:SECURITY_SOLTION AND ImplementerName=:IMPLEMENTERNAME AND Team_Leader=:Team_Lead AND Developer=:developer AND Customer_name=:customerName");
				query.setParameter("PRODUCT_SUIT", productsuit);
				query.setParameter("SECURITY_SOLTION", productname);
				query.setParameter("IMPLEMENTERNAME", implementerName);
				query.setParameter("Team_Lead", tlname);
				query.setParameter("developer", developer);
				query.setParameter("customerName", customerName);
				List data = query.list();

				if (!data.isEmpty()) {
					status = "duplicate";
				} else {
					TlMaster product = new TlMaster();

					product.setSR_NO(srno);
					product.setPRODUCT_SUIT(productsuit);
					product.setSECURITY_SOLTION(productname);
					product.setImplementerName(implementerName);
					product.setTeam_Leader(tlname);
					product.setDeveloper(developer);
					product.setCustomer_name(customerName);
					
					getSession().save(product);
					status = "success";
				}
			} catch (Exception e) {
				e.printStackTrace();
			}

			return status;
		}

		@Override
		public String deleteTlMaster(int srno) {
			String status = null;

			try {
				Query query = sessionFactory.getCurrentSession()
						.createQuery("delete from TlMaster where SR_NO = :SR_NO");

				query.setParameter("SR_NO", srno);
				int i = query.executeUpdate();
				if (i == 0) {
					status = "error";
				} else {

					status = "success";
				}
			} catch (Exception e) {
				e.printStackTrace();
			}
			return status;
		}

		@Override
		public String updateTLMaster(String productsuitupdate, String securitysolutionupdate, String tlname, int srno,
				String updImplementerName) {
			String status = null;

			try {
				Query query2 = getSession().createQuery(
						"from TlMaster where PRODUCT_SUIT=:PRODUCT_SUIT AND SECURITY_SOLTION=:SECURITY_SOLTION AND Team_Leader=:tlname AND ImplementerName=:IMPLEMENTERNAME");
				query2.setParameter("PRODUCT_SUIT", productsuitupdate);
				query2.setParameter("SECURITY_SOLTION", securitysolutionupdate);
				query2.setParameter("tlname", tlname);
				query2.setParameter("IMPLEMENTERNAME", updImplementerName);
				TlMaster data1 = (TlMaster) query2.uniqueResult();

				if (data1 != null) {
					status = "duplicate";
				} else {
					Query query = getSession().createQuery(
							"update TlMaster set PRODUCT_SUIT=:PRODUCT_SUIT, SECURITY_SOLTION=:SECURITY_SOLTION, Team_Leader=:tlname,ImplementerName=:IMPLEMENTERNAME where SR_NO=:SR_NO");

					query.setParameter("PRODUCT_SUIT", productsuitupdate);
					query.setParameter("SECURITY_SOLTION", securitysolutionupdate);
					query.setParameter("tlname", tlname);
					query.setParameter("IMPLEMENTERNAME", updImplementerName);
					query.setParameter("SR_NO", srno);
					int i = query.executeUpdate();

					if (i == 0) {
						status = "error";
					} else {
						status = "success";
					}
				}
			} catch (Exception e) {
				e.printStackTrace();
				// Handle the exception appropriately, e.g., log it or return an error status
				status = "error";
			}
			return status;
		}

