		@Override
		public String updateClientMaster(String srno, String customer, String prodSuite, String prodTool,
			String managerName, String functionName, String toDateUpdate, String statusUpdate) {
		String status = null;
		int srNo = Integer.parseInt(srno);
		try {

			Query query2 = getSession().createQuery("from ClientMaster where Customer_Name='" + customer
					+ "' AND Product_Suite='" + prodSuite + "'" + " and Product_Tool='" + prodTool
					+ "'   and Product_Manager='" + managerName + "'  and Function_name='" + functionName
					+ "'  and Target_Date='" + toDateUpdate + "' and Status='" + statusUpdate + "'  ");
			List<ClientMaster> data1 = query2.list();
			//// //System.out.println("data:123" + data1);
			if (!data1.isEmpty()) {
				status = "duplicate";
			} else {

				System.out.println("statusUpdateee " + statusUpdate);
				try {

					if (statusUpdate.equalsIgnoreCase("On Hold")) {

						Query query = getSession().createQuery("UPDATE DaywiseTask SET STATUS = :status "
								+ "WHERE PRODUCTSUIT = :prodSuite " + "AND PRODUCTTOOL = :prodTool "
								+ "AND CUSTOMERNAME = :customerName " + "AND STATUS = :pStatus");

						query.setParameter("status", "On Hold");
						query.setParameter("prodSuite", prodSuite);
						query.setParameter("prodTool", prodTool);
						query.setParameter("customerName", customer);
						query.setParameter("pStatus", "Pending");

						int result = query.executeUpdate();
						System.out.println("executeUpdate: " + result);

					} else if (statusUpdate.equalsIgnoreCase("Pending")) {

						Query query = getSession().createQuery("UPDATE DaywiseTask SET STATUS = :status "
								+ "WHERE PRODUCTSUIT = :prodSuite " + "AND PRODUCTTOOL = :prodTool "
								+ "AND CUSTOMERNAME = :customerName " + "AND STATUS = :pStatus");

						query.setParameter("status", "Pending");
						query.setParameter("prodSuite", prodSuite);
						query.setParameter("prodTool", prodTool);
						query.setParameter("customerName", customer);
						query.setParameter("pStatus", "On Hold");

						int result = query.executeUpdate();
						System.out.println("executeUpdate: " + result);
					}

				} catch (Exception e) {
					e.printStackTrace();
					// TODO: handle exception
				}

				Query query = getSession().createQuery("UPDATE ClientMaster SET Customer_Name = :customer, "
						+ "Product_Suite = :prodSuite, " + "Product_Tool = :prodTool, "
						+ "Product_Manager = :managerName, " + "Function_name = :functionName, "
						+ "Target_Date = :toDateUpdate, " + "Status = :statusUpdate " + "WHERE SR_NO = :srno");

				query.setParameter("customer", customer);
				query.setParameter("prodSuite", prodSuite);
				query.setParameter("prodTool", prodTool);
				query.setParameter("managerName", managerName);
				query.setParameter("functionName", functionName);
				query.setParameter("toDateUpdate", toDateUpdate);
				query.setParameter("statusUpdate", statusUpdate);
				query.setParameter("srno", srNo);

				int i = query.executeUpdate();

				if (i == 0) {
					status = "error";
				} else {

					status = "success";
				}
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		return status;

	}

