		@Override
	public String updateUserActivity(String username, String activities, String userfullname) {

		String status = null;
		String prevActivity = "";
		String prevDate = "";
		String formattedDate = null;
		String lastLogin = "";

		try {
			SimpleDateFormat dateFormat = new SimpleDateFormat("dd.MM.yyyy");
			Date curdate = new Date();
			String currentDateTime = dateFormat.format(curdate);

			Session session = getSession();
			Query query1 = session.createQuery("from loginmaster where USERNAME = :username");
			query1.setParameter("username", username);
			List<loginmaster> dataList = query1.list();

			JSONObject userActivityJson = new JSONObject();
			for (loginmaster data : dataList) {
				
				if (data.getLast_login_time() == null || data.getLast_login_time().isEmpty() || data.getLast_login_time().contentEquals("")) {
					lastLogin = "";
				} else {
					lastLogin = data.getLast_login_time();
				}
				
				if (data.getUSER_ACTIVITY() == null || data.getUSER_ACTIVITY().isEmpty()) {
					prevActivity = "{}";
				} else {
					prevActivity = data.getUSER_ACTIVITY();
				}

				userActivityJson = new JSONObject(prevActivity);

				prevDate = data.getLast_login_time();
				String[] parts = prevDate.split("\\s+");
				formattedDate = parts[0];
			}

			// Check if there's any existing activity
			if (userActivityJson.length() > 0) {
				Date minDate = null;

				for (String dateKey : userActivityJson.keySet()) {
					Date date = dateFormat.parse(dateKey);
					if (minDate == null || date.before(minDate)) {
						minDate = date;
					}
				}

				if (minDate != null && (curdate.getTime() - minDate.getTime()) > (15L * 24 * 60 * 60 * 1000)) {
					// More than 15 days have passed since the first activity date
					userActivityJson = new JSONObject(); // Clear the existing data
					userActivityJson.put(currentDateTime, activities); // Add new data
				} else {
					if (userActivityJson.has(currentDateTime)) {
						String existingActivities = userActivityJson.getString(currentDateTime);
						List<String> activityList = new ArrayList<>(Arrays.asList(existingActivities.split(",")));

						// Add new activities to the list, maintaining order and avoiding duplicates
						for (String activity : activities.split(",")) {
							if (!activityList.contains(activity)) {
								activityList.add(activity);
							}
						}

						String updatedActivities = String.join(",", activityList);
						userActivityJson.put(currentDateTime, updatedActivities);
					} else {
						userActivityJson.put(currentDateTime, activities);
					}
				}
			} else {
				userActivityJson.put(currentDateTime, activities);
			}

			Query query = session
					.createQuery("UPDATE loginmaster SET USER_ACTIVITY = :activities WHERE USERNAME = :username");
			query.setParameter("username", username);
			query.setParameter("activities", userActivityJson.toString());

			int i = query.executeUpdate();
			if (i == 0) {
				status = "error";
			} else {
				status = "success";
				
				
				
				try {
					
					SimpleDateFormat dateFormatNew = new SimpleDateFormat("dd.MM.yyyy HH:mm");
					Date curdateNew = new Date();
					String currentDateTimeNew = dateFormatNew.format(curdateNew);
					
					if(!(lastLogin.split(" ")[0].contains(currentDateTime))) {
						Query queryUp = session .createQuery("UPDATE loginmaster SET last_login_time = :time WHERE USERNAME = :username");
						queryUp.setParameter("username", username);
						queryUp.setParameter("time", currentDateTimeNew);
	
						int iUp = queryUp.executeUpdate();
					} 
				} catch (Exception e) {
					// TODO: handle exception
				}
				
				
				
			}
		} catch (Exception e) {
			status = "Ex error";
			e.printStackTrace();
		}

		return status;

	}

