		@Override
		public String ClientMasterSupport(String productSuit, String securitytool, String customerName,
				String prodManager, String functionName, String targetDate, String status, String role) {
			String status1 = null;
			try {
				Session s = getSession();
				int srno = 0;
				try {
					Criteria crit = sessionFactory.getCurrentSession().createCriteria(ClientMasterSupport.class)
							.setProjection(Projections.max("SR_NO"));
					Integer srno1 = (Integer) crit.uniqueResult();

					if (srno1 != null) {
						srno = srno1.intValue() + 1;

					} else {
						srno = 1;
					}
				} catch (Exception e) {

					e.printStackTrace();
				}

				Query query = sessionFactory.getCurrentSession().createQuery(
						"from ClientMasterSupport where Product_Suite=:PRODUCT_SUIT AND Product_Tool=:Product_Tool AND Customer_Name=:Customer_Name AND Product_Manager=:Product_Manager AND Function_name=:functionName ");
				query.setParameter("PRODUCT_SUIT",productSuit );
				query.setParameter("Product_Tool", securitytool);
				query.setParameter("Customer_Name", customerName);
				query.setParameter("Product_Manager", prodManager);
				query.setParameter("functionName",functionName);
//				query.setParameter("sts",status);
				List data = query.list();

				if (!data.isEmpty()) {
					status1 = "duplicate";
				} else {
					 ClientMasterSupport client = new ClientMasterSupport();

					 client.setSR_NO(srno);
					 client.setProduct_Suite(productSuit);
					 client.setProduct_Tool(securitytool);
					 client.setCustomer_Name(customerName);
					 client.setProduct_Manager(prodManager);
					 client.setFunction_name(functionName);
					 
					 if(targetDate == "" || targetDate == null || targetDate=="undefined")
					 {
						 client.setTarget_Date("NA");
					 }
					 else {
						 client.setTarget_Date(targetDate);
					 }
					 
					 client.setStatus(status);
					getSession().save(client);
					status1 = "success";
				}
			} catch (Exception e) {
				e.printStackTrace();
			}

			return status1;
		}

