		@Override
		public JSONArray CompletedDetailsByCusManAndTLNew(String projectNamesN, String prodmgrN,
				String teamLeaderNameN,String methodName) {
			JSONArray array1 = new JSONArray();
		    System.out.println("in ActivitiesCompletedcountNew");
		    Query query = null;

		    try {
		        if (methodName.equalsIgnoreCase("TotalProjects")) {
		            System.out.println("in totallll");
		            if(projectNamesN.length()>0 && prodmgrN.length()>0)
						{
							query = getSession().createQuery("select distinct CUSTOMERNAME,MANAGER_NAME,PRODUCTSUIT,PRODUCTTOOL,FUNCTION_NAME,DESCRIPTION,TEAM_LEADER,DEVELOPER_NAME,TaskUpdateDate,END_DATE,STATUS,updateDateCount from DaywiseTask where MANAGER_NAME!='' AND CUSTOMERNAME='"+projectNamesN+"' AND MANAGER_NAME='"+prodmgrN+"' AND TEAM_LEADER='"+teamLeaderNameN+"' ORDER BY CUSTOMERNAME");
						}
						else if(projectNamesN.length()==0 && prodmgrN.length()>0 && teamLeaderNameN.length()>0)
						{
							query = getSession().createQuery("select distinct CUSTOMERNAME,MANAGER_NAME,PRODUCTSUIT,PRODUCTTOOL,FUNCTION_NAME,DESCRIPTION,TEAM_LEADER,DEVELOPER_NAME,TaskUpdateDate,END_DATE,STATUS,updateDateCount from DaywiseTask where MANAGER_NAME!='' AND MANAGER_NAME='"+prodmgrN+"' AND TEAM_LEADER='"+teamLeaderNameN+"' ORDER BY CUSTOMERNAME");
						}
						else if(projectNamesN.length()>0 && prodmgrN.length()==0 && teamLeaderNameN.length()>0)
						{
							query = getSession().createQuery("select distinct CUSTOMERNAME,MANAGER_NAME,PRODUCTSUIT,PRODUCTTOOL,FUNCTION_NAME,DESCRIPTION,TEAM_LEADER,DEVELOPER_NAME,TaskUpdateDate,END_DATE,STATUS,updateDateCount from DaywiseTask where MANAGER_NAME!='' AND CUSTOMERNAME='"+projectNamesN+"' AND TEAM_LEADER='"+teamLeaderNameN+"' ORDER BY CUSTOMERNAME");
						}
						else {
							query = getSession().createQuery("select distinct CUSTOMERNAME,MANAGER_NAME,PRODUCTSUIT,PRODUCTTOOL,FUNCTION_NAME,DESCRIPTION,TEAM_LEADER,DEVELOPER_NAME,TaskUpdateDate,END_DATE,STATUS,updateDateCount from DaywiseTask where MANAGER_NAME!='' AND TEAM_LEADER='"+teamLeaderNameN+"' ORDER BY CUSTOMERNAME");
		
						}

		            List<Object[]> results = query.list();

		            for (Object[] row : results) {
		                JSONArray array = new JSONArray();

		                array.put(row[0]); // Customer_Name
		                array.put(row[1]); // Manager Name
		                array.put(row[2]); // Product_Suite
		                array.put(row[3]); // Product_Tool
		                array.put(row[4]); // Function_Name
		                array.put(row[5]); // Description
		                array.put(row[6]); // TEAM_LEADER
		                array.put(row[7]); // DEVELOPER_NAME
		                array.put(row[8]); // TaskUpdateDate
		                array.put(row[9]); // END_DATE
		                array.put(row[10]); // STATUS
		                array.put(row[11]); // updateDateCount

		                
		                System.out.println("Row 10: "+row[10]);
		                try {
		                    if (row[10].equals("Pending")) {
		                        String endDateString = row[9].toString();

		                        if (!(endDateString.equals("NA") || endDateString.isEmpty())) {
		                            SimpleDateFormat dateFormat = new SimpleDateFormat("dd.MM.yyyy");

		                            Date currentDate = new Date();
		                            Date endDate = dateFormat.parse(endDateString);

		                            System.out.println("endDate " + endDate + " , " + currentDate);

		                            if (currentDate.after(endDate)) {
		                                array.put("Delayed");
		                            } else if (endDate.after(currentDate)) {
		                                array.put("Pending");
		                            }
		                        } else {
		                            array.put("Pending");
		                        }
		                    } else {
		                        array.put(row[10]);
		                    }
		                } catch (Exception e) {
		                    e.printStackTrace();
		                    array.put("Error processing status");
		                }

		                array1.put(array);
		            }
		        } else {
		        	System.out.println("inside else");
		        	if(projectNamesN.length()>0 && prodmgrN.length()>0)
						{
							query = getSession().createQuery("select distinct CUSTOMERNAME,MANAGER_NAME,PRODUCTSUIT,PRODUCTTOOL,FUNCTION_NAME,DESCRIPTION,TEAM_LEADER,DEVELOPER_NAME,TaskUpdateDate,END_DATE,STATUS,updateDateCount from DaywiseTask where MANAGER_NAME!='' AND CUSTOMERNAME='"+projectNamesN+"' AND MANAGER_NAME='"+prodmgrN+"' AND TEAM_LEADER='"+teamLeaderNameN+"' ORDER BY CUSTOMERNAME");
						}
						else if(projectNamesN.length()==0 && prodmgrN.length()>0 && teamLeaderNameN.length()>0)
						{
							query = getSession().createQuery("select distinct CUSTOMERNAME,MANAGER_NAME,PRODUCTSUIT,PRODUCTTOOL,FUNCTION_NAME,DESCRIPTION,TEAM_LEADER,DEVELOPER_NAME,TaskUpdateDate,END_DATE,STATUS,updateDateCount from DaywiseTask where MANAGER_NAME!='' AND MANAGER_NAME='"+prodmgrN+"' AND TEAM_LEADER='"+teamLeaderNameN+"' ORDER BY CUSTOMERNAME");
						}
						else if(projectNamesN.length()>0 && prodmgrN.length()==0 && teamLeaderNameN.length()>0)
						{
							query = getSession().createQuery("select distinct CUSTOMERNAME,MANAGER_NAME,PRODUCTSUIT,PRODUCTTOOL,FUNCTION_NAME,DESCRIPTION,TEAM_LEADER,DEVELOPER_NAME,TaskUpdateDate,END_DATE,STATUS,updateDateCount from DaywiseTask where MANAGER_NAME!='' AND CUSTOMERNAME='"+projectNamesN+"' AND TEAM_LEADER='"+teamLeaderNameN+"' ORDER BY CUSTOMERNAME");
						}
						else {
							query = getSession().createQuery("select distinct CUSTOMERNAME,MANAGER_NAME,PRODUCTSUIT,PRODUCTTOOL,FUNCTION_NAME,DESCRIPTION,TEAM_LEADER,DEVELOPER_NAME,TaskUpdateDate,END_DATE,STATUS,updateDateCount from DaywiseTask where MANAGER_NAME!='' AND TEAM_LEADER='"+teamLeaderNameN+"' ORDER BY CUSTOMERNAME");
		
						}
		            
		            List<Object[]> results = query.list();
		            for (Object[] row : results) {
		                JSONArray array = new JSONArray();
		                for (Object cell : row) {
		                    array.put(cell);
		                }
		                array1.put(array);
		            }
		        }
		    } catch (Exception e) {
		        e.printStackTrace();
		        // TODO: handle exception
		    }

		    System.out.println("NIIIII" + array1);
		    return array1;
		}
		
