				@Override
				public String bellNotification(String uname) {
				    String status = "error"; 
				    
				    LocalDate currentDate = LocalDate.now();
			        DateTimeFormatter outputCurrentDate = DateTimeFormatter.ofPattern("dd.MM.yyyy");
			        String formattedDate = currentDate.format(outputCurrentDate);
				    
				    Query query1 = getSession().createQuery("select distinct FULL_NAME from loginmaster where USERNAME='" + uname + "'");
		            String devName = (String) query1.uniqueResult();
				    
				    String updateQuery = "UPDATE DaywiseTask SET ONE_TIME = :oneTime WHERE DEVELOPER_NAME = :devName";
				    String countQuery = null;

				    try {
				        
				        Query updateQueryObj = sessionFactory.getCurrentSession().createQuery(updateQuery);
				        updateQueryObj.setParameter("oneTime", "false");
				        updateQueryObj.setParameter("devName", devName);
//				        updateQueryObj.setParameter("assign_date",assign_date);

				        int updateCount = updateQueryObj.executeUpdate();
				        System.out.println("Count of updated one_time value: " + updateCount);

				        
				        if (updateCount > 0) {
				        	
				            countQuery = "SELECT COUNT(SR_NO) FROM DaywiseTask WHERE DEVELOPER_NAME='"+devName+"' AND Assign_date='"+formattedDate+"'";

				            Query countQueryObj = sessionFactory.getCurrentSession().createQuery(countQuery);
				            Long countResult = (Long) countQueryObj.uniqueResult();

				            System.out.println("Notification value: " + countResult);
				            status = String.valueOf(countResult);  

				        } else {
				            System.out.println("No rows were updated.");
				        }

				    } catch (Exception e) {
				        e.printStackTrace();
				        status = "error";  
				    }

				    return status;
			}

				
