				@Override
				public String saveTlMasterForMan(String productsuit, String productname, String unit, String implementerName,
						String tlname, String developer, String customerName) {
					
					
					String status = null;
					try {
						Session s = getSession();
						int srno = 0;

						String implementorUsername = "";
						try {
							Criteria crit = sessionFactory.getCurrentSession().createCriteria(TlMaster.class)
									.setProjection(Projections.max("SR_NO"));
							Integer srno1 = (Integer) crit.uniqueResult();

							if (srno1 != null) {
								srno = srno1.intValue() + 1;

							} else {
								srno = 1;
							}
						} catch (Exception e) {

							e.printStackTrace();
						}



//						Query query = sessionFactory.getCurrentSession().createQuery(
//								"from TlMasterSupport where PRODUCT_SUIT=:PRODUCT_SUIT AND SECURITY_SOLTION=:SECURITY_SOLTION AND ImplementerName=:IMPLEMENTERNAME AND Team_Leader=:Team_Lead AND Developer=:developer AND Customer_name=:customerName");
						
						Query query = sessionFactory.getCurrentSession().createQuery(
								"from TlMaster where Developer=:developer");
						
//						query.setParameter("IMPLEMENTERNAME", implementerName);
//						query.setParameter("Team_Lead", tlname);
						query.setParameter("developer", developer);
						List data = query.list();

						if (!data.isEmpty()) {
							status = "duplicate";
						} else {
							TlMaster product = new TlMaster();

							product.setSR_NO(srno);
							product.setPRODUCT_SUIT("NA");
							product.setSECURITY_SOLTION("NA");
							
							if (implementerName.equals("null") || implementerName.isEmpty()) {
							    product.setImplementerName("NA");
							} else {
							    product.setImplementerName(implementerName);
							}

							if (tlname.equals("null") || tlname.isEmpty()) {
							    product.setTeam_Leader("NA");
							} else {
							    product.setTeam_Leader(tlname);
							}

							if (developer.equals("null") || developer.isEmpty()) {
							    product.setDeveloper("NA");
							} else {
							    product.setDeveloper(developer);
							}

							
//							product.setImplementerName("NA");
//							product.setTeam_Leader("NA");
//							product.setDeveloper("NA");
							product.setCustomer_name("NA");
							
							getSession().save(product);
							status = "success";
						}
					} catch (Exception e) {
						e.printStackTrace();
					}

					return status;
				
				}

